#!/usr/bin/env node
// Probe helper for Python-Markdown 3.10.2 reference executable.
//
//   node /tmp/pm.mjs '<markdown text>'      -> runs text through all 3 modes
//   node /tmp/pm.mjs --file path.md         -> same, text read from a file
//
// In the inline form, the two-character sequences \n and \t are expanded to
// real newline / tab. Use --file for anything with tricky quoting.
//
// Modes: a = markdown.markdown(x)                (core, no extensions)
//        b = markdown.markdown(x, ['tables'])
//        c = markdown.markdown(x, ['extra'])
import { execFileSync } from 'node:child_process';
import { readFileSync } from 'node:fs';

const EXE = '/workspace/dataset/test11_executable';
const SEP = 'ZqZsepZqZ';

function unesc(s) {
  let out = '';
  for (let i = 0; i < s.length; i++) {
    if (s[i] === '\\' && i + 1 < s.length) {
      const n = s[i + 1];
      if (n === 'n') { out += '\n'; i++; continue; }
      if (n === 't') { out += '\t'; i++; continue; }
      if (n === 'r') { out += '\r'; i++; continue; }
      if (n === '\\') { out += '\\'; i++; continue; }
    }
    out += s[i];
  }
  return out;
}

function run(args) {
  try {
    return { out: execFileSync(EXE, args, { encoding: 'utf8', maxBuffer: 1 << 28 }), rc: 0 };
  } catch (e) {
    return { out: (e.stdout || '') + (e.stderr || ''), rc: e.status };
  }
}

let text;
if (process.argv[2] === '--file') {
  text = readFileSync(process.argv[3], 'utf8');
} else if (process.argv[2] !== undefined) {
  text = unesc(process.argv[2]);
} else {
  console.error('usage: node /tmp/pm.mjs <text>   |   node /tmp/pm.mjs --file <path>');
  process.exit(2);
}

const r1 = run(['--a', text, '--b', SEP, '--c', text]);
const p1 = r1.out.split(SEP + '\n');
const core = p1[0] === undefined ? '' : p1[0];
const extra = p1[1] === undefined ? '' : p1[1];

const r2 = run(['--a', SEP, '--b', text, '--c', SEP]);
const p2 = r2.out.split(SEP + '\n');
const tables = p2[1] === undefined ? '' : p2[1];

console.log('INPUT       ' + JSON.stringify(text));
console.log('--- core (no extensions) ---');
process.stdout.write(core);
console.log('CORE_JSON   ' + JSON.stringify(core));
console.log('--- tables ---');
process.stdout.write(tables);
console.log('TABLES_JSON ' + JSON.stringify(tables));
console.log('--- extra ---');
process.stdout.write(extra);
console.log('EXTRA_JSON  ' + JSON.stringify(extra));
console.log('RC ' + r1.rc + ' ' + r2.rc);

