#!/usr/bin/env node
// BUILD-TIME ONLY. Not shipped, not imported by /output code.
// Emits /output/lib/core/unicode-tables.mjs: packed codepoint ranges so the
// runtime can answer Python's str.isalnum() / \w / \s questions with a binary
// search instead of a pattern engine.
import { writeFileSync } from 'node:fs';

function ranges(test) {
  const out = [];
  let start = -1;
  for (let cp = 0; cp <= 0x10ffff; cp++) {
    if (cp >= 0xd800 && cp <= 0xdfff) {           // lone surrogates: never members
      if (start !== -1) { out.push([start, cp - 1]); start = -1; }
      continue;
    }
    const hit = test(String.fromCodePoint(cp));
    if (hit && start === -1) start = cp;
    else if (!hit && start !== -1) { out.push([start, cp - 1]); start = -1; }
  }
  if (start !== -1) out.push([start, 0x10ffff]);
  return out;
}

// Python re \w for str  ==  str.isalnum() or '_'  ==  L* + N* + '_'
const wordRe = /[\p{L}\p{N}]/u;
// Python str.isspace(): Zs + \t\n\v\f\r + \x1c-\x1f + \x85 + Zl + Zp
const spaceRe = /[\p{Zs}\p{Zl}\p{Zp}]/u;
const EXTRA_SPACE = new Set([0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x1c, 0x1d, 0x1e, 0x1f, 0x85]);

const word = ranges(c => wordRe.test(c));
const space = ranges(c => spaceRe.test(c) || EXTRA_SPACE.has(c.codePointAt(0)));

function flat(rs) {
  // flatten to [lo,hi,lo,hi,...] for a compact, fast binary search
  const a = [];
  for (const [lo, hi] of rs) { a.push(lo, hi); }
  return a;
}

const body = `// GENERATED FILE -- do not edit by hand.
// Packed codepoint ranges as flat [lo, hi, lo, hi, ...] pairs.
//
// WORD  mirrors Python's \`re\` \\w for \`str\`: everything \`str.isalnum()\`
//       accepts (Unicode categories L* and N*) plus the underscore, which is
//       added by the predicate rather than stored here.
// SPACE mirrors Python's \`str.isspace()\`: the Unicode separator categories
//       plus the ASCII control whitespace and U+0085.

export const WORD_RANGES = Object.freeze([
${chunk(flat(word))}
]);

export const SPACE_RANGES = Object.freeze([
${chunk(flat(space))}
]);
`;

function chunk(arr) {
  const lines = [];
  for (let i = 0; i < arr.length; i += 16) {
    lines.push('  ' + arr.slice(i, i + 16).join(', ') + ',');
  }
  return lines.join('\n');
}

writeFileSync('/output/lib/core/unicode-tables.mjs', body);
console.log('word ranges:', word.length, ' space ranges:', space.length);
console.log('bytes:', body.length);

