// Character classification and low-level scanning primitives.
//
// Everything here is a codepoint test or an index-walking helper. The parser is
// built entirely out of these so that block and inline structure is recognised
// by an explicit scanner producing an AST, rather than by pattern substitution.

import { WORD_RANGES, SPACE_RANGES } from './unicode-tables.mjs';

function inRanges(ranges, cp) {
  let lo = 0;
  let hi = (ranges.length >> 1) - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    const a = ranges[mid << 1];
    const b = ranges[(mid << 1) + 1];
    if (cp < a) hi = mid - 1;
    else if (cp > b) lo = mid + 1;
    else return true;
  }
  return false;
}

/** Python `re` \w for `str`: `str.isalnum()` plus underscore. */
export function isWordChar(ch) {
  if (ch === undefined || ch === '') return false;
  const cp = ch.codePointAt(0);
  if (cp === 0x5f) return true;                                  // _
