// Shared constants: the sentinel characters Markdown uses to fence off content
// that must survive later passes untouched, plus the block-level tag set.

/** Start of placeholder sentinel (ASCII STX). */
export const STX = '';
/** End of placeholder sentinel (ASCII ETX). */
export const ETX = '';

export const INLINE_PLACEHOLDER_PREFIX = STX + 'klzzwxh:';
export const HTML_PLACEHOLDER_PREFIX = STX + 'wzxhzdk:';
export const TAG_PLACEHOLDER_PREFIX = STX + 'hzzhzkh:';

/** Stand-in for a literal ampersand that must not be re-escaped. */
export const AMP_SUBSTITUTE = STX + 'amp' + ETX;

export function inlinePlaceholder(n) {
  return INLINE_PLACEHOLDER_PREFIX + n + ETX;
}

export function htmlPlaceholder(n) {
  return HTML_PLACEHOLDER_PREFIX + n + ETX;
}

export function tagPlaceholder(n) {
  return TAG_PLACEHOLDER_PREFIX + n + ETX;
}

/** Default tab width used when expanding tabs and measuring indentation. */
export const TAB_LENGTH = 4;

/** The synthetic root element; stripped off before the output is returned. */
export const DOC_TAG = 'div';

/**
 * Elements that must not be wrapped in a `<p>`, plus elements whose contents
 * Markdown should leave alone. Drives paragraph wrapping and the prettify pass.
 */
export const BLOCK_LEVEL_ELEMENTS = [
  // Invalid to wrap in a `<p>`.
  'address', 'article', 'aside', 'blockquote', 'details', 'div', 'dl',
  'fieldset', 'figcaption', 'figure', 'footer', 'form', 'h1', 'h2', 'h3',
  'h4', 'h5', 'h6', 'header', 'hgroup', 'hr', 'main', 'menu', 'nav', 'ol',
  'p', 'pre', 'section', 'table', 'ul',
  // Contents should not be mucked with.
  'canvas', 'colgroup', 'dd', 'body', 'dt', 'group', 'iframe', 'li', 'legend',
  'math', 'map', 'noscript', 'output', 'object', 'option', 'progress', 'script',
  'style', 'summary', 'tbody', 'td', 'textarea', 'tfoot', 'th', 'thead', 'tr',
  'video',
];

/** Elements serialised in self-closing form under the XHTML output format. */
export const HTML_EMPTY = new Set([
  'area', 'base', 'basefont', 'br', 'col', 'embed', 'frame', 'hr', 'img',
  'input', 'isindex', 'link', 'meta', 'param', 'source', 'track', 'wbr',
]);

/** Pseudo-tags for comments and processing instructions in the tree. */
export const COMMENT = Symbol('Comment');
export const PROCESSING_INSTRUCTION = Symbol('ProcessingInstruction');

