// One-off patcher: swap the raw STX/ETX control bytes in constants.mjs for
// String.fromCharCode() calls so no source file carries invisible control chars.
import { readFileSync, writeFileSync } from 'node:fs';

const p = '/output/lib/core/constants.mjs';
let s = readFileSync(p, 'utf8');

const stxLine = 'export const STX = ' + "'" + String.fromCharCode(2) + "'" + ';';
const etxLine = 'export const ETX = ' + "'" + String.fromCharCode(3) + "'" + ';';

if (!s.includes(stxLine) || !s.includes(etxLine)) {
  console.error('expected raw-control declarations not found');
  process.exit(1);
}

s = s.split(stxLine).join('export const STX = String.fromCharCode(2);');
s = s.split(etxLine).join('export const ETX = String.fromCharCode(3);');

for (const ch of s) {
  const c = ch.codePointAt(0);
  if (c < 9 || (c > 13 && c < 32)) {
    console.error('raw control char still present: U+' + c.toString(16));
    process.exit(1);
  }
}

writeFileSync(p, s);
console.log('patched; file is free of raw control characters');

