// The document AST.
//
// Mirrors the ElementTree shape Markdown builds internally: every node carries
// `text` (content before its first child) and `tail` (content after its own
// closing tag), which is what lets inline content interleave with child
// elements without a separate text-node type.

import { COMMENT, PROCESSING_INSTRUCTION } from './constants.mjs';

export class Element {
  constructor(tag, attrib) {
    this.tag = tag;
    /** Insertion-ordered attributes. */
    this.attrib = new Map();
    /** Content between this element's start tag and its first child. */
    this.text = null;
    /** Content between this element's end tag and its next sibling. */
    this.tail = null;
    this.children = [];
    /**
     * Marks `text` as already-final content that later inline passes must not
     * descend into (code spans, stashed HTML). Stands in for the AtomicString
     * marker type, which has no JS equivalent for primitives.
     */
    this.textAtomic = false;
    if (attrib) {
      for (const k of Object.keys(attrib)) this.attrib.set(k, attrib[k]);
    }
  }

  set(key, value) {
    this.attrib.set(key, value);
    return this;
  }

  get(key, dflt = null) {
    return this.attrib.has(key) ? this.attrib.get(key) : dflt;
  }

  /** Set `text` and mark it as not-to-be-reprocessed. */
  setAtomicText(value) {
    this.text = value;
    this.textAtomic = true;
    return this;
  }

  append(child) {
    this.children.push(child);
    return child;
  }

  extend(children) {
    for (const c of children) this.children.push(c);
  }

  insert(index, child) {
    this.children.splice(index, 0, child);
    return child;
  }

  remove(child) {
    const i = this.children.indexOf(child);
    if (i !== -1) this.children.splice(i, 1);
  }

  indexOf(child) {
    return this.children.indexOf(child);
  }

  get length() {
    return this.children.length;
  }

  at(index) {
    return this.children[index < 0 ? this.children.length + index : index];
  }

  /** Depth-first walk over this element and all descendants. */
  *iter(tag = null) {
    if (tag === null || this.tag === tag) yield this;
    for (const child of this.children) {
      if (child instanceof Element) yield* child.iter(tag);
    }
  }

  /** Direct children matching `tag`. */
  findAll(tag) {
    const out = [];
    for (const c of this.children) if (c instanceof Element && c.tag === tag) out.push(c);
    return out;
  }
}

export function subElement(parent, tag, attrib) {
  return parent.append(new Element(tag, attrib));
}

export function comment(text) {
  const el = new Element(COMMENT);
  el.text = text;
  return el;
}

export function processingInstruction(text) {
  const el = new Element(PROCESSING_INSTRUCTION);
  el.text = text;
  return el;
}

/** Deep copy, preserving attribute order and atomic-text marks. */
export function cloneElement(el) {
  const copy = new Element(el.tag);
  for (const [k, v] of el.attrib) copy.attrib.set(k, v);
  copy.text = el.text;
  copy.tail = el.tail;
  copy.textAtomic = el.textAtomic;
  for (const c of el.children) copy.children.push(cloneElement(c));
  return copy;
}

