// XHTML serialization of the document AST.
//
// Attribute order is lexical by name, void elements close as `<tag />`, and
// ampersands are left alone only when they begin something that already looks
// like a character reference.

import { COMMENT, PROCESSING_INSTRUCTION, HTML_EMPTY } from './constants.mjs';
import { isAsciiAlnum, isDigit, isHexDigit } from './chars.mjs';

/**
 * True when `text` has a character-reference-shaped run starting at `i`
 * (which points at the `&`): `&#123;`, `&#xAF;` or `&name;` with an
 * alphanumeric-only name. Such runs are emitted verbatim.
 */
function looksLikeCharRef(text, i) {
  let j = i + 1;
  if (j >= text.length) return false;
  if (text[j] === '#') {
    j++;
    if (j < text.length && (text[j] === 'x' || text[j] === 'X')) {
      // Markdown only recognises the lowercase `x` form here.
      if (text[j] !== 'x') return false;
      j++;
      const start = j;
      while (j < text.length && isHexDigit(text[j])) j++;
      if (j === start) return false;
      return text[j] === ';';
    }
    const start = j;
    while (j < text.length && isDigit(text[j])) j++;
    if (j === start) return false;
    return text[j] === ';';
  }
  const start = j;
  while (j < text.length && isAsciiAlnum(text[j])) j++;
  if (j === start) return false;
  return text[j] === ';';
}

/** Escape element text / tails: `&` (conditionally), `<` and `>`. */
export function escapeCdata(text) {
  let out = '';
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (ch === '&') out += looksLikeCharRef(text, i) ? '&' : '&amp;';
    else if (ch === '<') out += '&lt;';
    else if (ch === '>') out += '&gt;';
    else out += ch;
  }
  return out;
}

/** Escape attribute values: as above, plus `"` and newlines. */
export function escapeAttrib(text) {
  let out = '';
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (ch === '&') out += looksLikeCharRef(text, i) ? '&' : '&amp;';
    else if (ch === '<') out += '&lt;';
    else if (ch === '>') out += '&gt;';
    else if (ch === '"') out += '&quot;';
    else if (ch === '\n') out += '&#10;';
    else out += ch;
  }
  return out;
}

function serializeInto(buf, el) {
  const tag = el.tag;

  if (tag === COMMENT) {
    buf.push('<!--' + (el.text === null ? '' : el.text) + '-->');
  } else if (tag === PROCESSING_INSTRUCTION) {
    buf.push('<?' + (el.text === null ? '' : el.text) + '?>');
  } else if (tag === null) {
    // Transparent node: contributes its content but no tags of its own.
    if (el.text) buf.push(escapeCdata(el.text));
    for (const child of el.children) serializeInto(buf, child);
  } else {
    buf.push('<' + tag);
    const keys = [...el.attrib.keys()].sort();
    for (const k of keys) {
      const v = el.attrib.get(k);
      buf.push(' ' + k + '="' + escapeAttrib(v === null || v === undefined ? '' : String(v)) + '"');
    }
    const lower = String(tag).toLowerCase();
    if (HTML_EMPTY.has(lower)) {
      buf.push(' />');
    } else {
      buf.push('>');
      if (el.text) {
        // `script`/`style` bodies are CDATA in HTML and must not be escaped.
        buf.push(lower === 'script' || lower === 'style' ? el.text : escapeCdata(el.text));
      }
      for (const child of el.children) serializeInto(buf, child);
      buf.push('</' + tag + '>');
    }
  }

  if (el.tail) buf.push(escapeCdata(el.tail));
}

/** Serialize an element tree to an XHTML string. */
export function toHtmlString(root) {
  const buf = [];
  serializeInto(buf, root);
  return buf.join('');
}

