// Priority-ordered registry of pipeline components.
//
// Processors are registered under a name with a numeric priority and iterate
// highest-priority-first. Extensions rely on being able to look a component up
// by name and insert relative to it, so names stay addressable after sorting.

export class Registry {
  constructor() {
    this._entries = [];   // { name, priority, value }
    this._sorted = null;
  }

  register(value, name, priority) {
    this.deregister(name, false);
    this._entries.push({ name, priority, value });
    this._sorted = null;
    return this;
  }

  deregister(name, strict = true) {
    const i = this._entries.findIndex(e => e.name === name);
    if (i === -1) {
      if (strict) throw new Error(`No item named "${name}" exists.`);
      return this;
    }
    this._entries.splice(i, 1);
    this._sorted = null;
    return this;
  }

  has(name) {
    return this._entries.some(e => e.name === name);
  }

  get(name) {
    const e = this._entries.find(x => x.name === name);
    if (!e) throw new Error(`No item named "${name}" exists.`);
    return e.value;
  }

  /** Highest priority first; ties keep registration order. */
  get ordered() {
    if (this._sorted === null) {
      this._sorted = this._entries
        .map((e, i) => ({ e, i }))
        .sort((x, y) => (y.e.priority - x.e.priority) || (x.i - y.i))
        .map(x => x.e.value);
    }
    return this._sorted;
  }

  [Symbol.iterator]() {
    return this.ordered[Symbol.iterator]();
  }
}

