// is what keeps Markdown from escaping or reformatting embedded markup.

import { htmlPlaceholder } from './constants.mjs';

export class HtmlStash {
  constructor() {
    this.htmlCounter = 0;
    this.rawHtmlBlocks = [];
    this.tagCounter = 0;
    this.tagData = [];   // { tag, attrs, left_index, right_index }
  }

  /** Stash `html` and return the placeholder that stands in for it. */
  store(html) {
    this.rawHtmlBlocks.push(html);
    const placeholder = this.getPlaceholder(this.htmlCounter);
    this.htmlCounter += 1;
    return placeholder;
  }

  reset() {
    this.htmlCounter = 0;
    this.rawHtmlBlocks = [];
  }

  getPlaceholder(key) {
    return htmlPlaceholder(key);
  }
}

