// Line-level passes that run before any block is parsed.

import { STX, ETX } from './constants.mjs';
import { expandTabs, replaceAll } from './chars.mjs';

/**
 * Fold the source into a canonical shape: no stray sentinel characters, Unix
 * newlines, a guaranteed pair of trailing blank lines so the last block always
 * terminates, tabs expanded to columns, and whitespace-only lines emptied so
 * they reliably separate blocks.
 */
export class NormalizeWhitespace {
  constructor(md) {
    this.md = md;
  }

  run(lines) {
    let source = lines.join('\n');
    source = replaceAll(source, STX, '');
    source = replaceAll(source, ETX, '');
    source = replaceAll(source, '\r\n', '\n');
    source = replaceAll(source, '\r', '\n');
    source = source + '\n\n';
    source = expandTabs(source, this.md.tabLength);
    source = blankOutSpaceOnlyLines(source);
    return source.split('\n');
  }
}

/**
 * Drop runs of spaces that make up an entire line, so `"a\n   \nb"` separates
 * two blocks exactly like `"a\n\nb"`. Only lines preceded by a newline qualify,
 * which leaves a space-indented first line alone.
 */
function blankOutSpaceOnlyLines(source) {
  let out = '';
  let i = 0;
  while (i < source.length) {
    if (i > 0 && source[i - 1] === '\n' && source[i] === ' ') {
      let j = i;
      while (j < source.length && source[j] === ' ') j++;
      if (j < source.length && source[j] === '\n') {
        out += '\n';          // the run of spaces is discarded
        i = j + 1;
        continue;
      }
    }
    out += source[i];
    i++;
  }
  return out;
}

