// Block-level parsing driver.
//
// The document is split on blank lines into a work queue of blocks. Each block
// is offered to the registered processors in priority order; the first one that
// claims it consumes it, and may push remainders back onto the front of the
// queue. Processors recurse through `parseBlocks` to build nested structure,
// so the queue plus the parent element is the entire parser state.

import { Element } from './element.mjs';

/** A stack of context labels ("list", "looselist", "detabbed", ...). */
export class State {
  constructor() {
    this._stack = [];
  }

  set(state) {
    this._stack.push(state);
  }

  reset() {
    this._stack.pop();
  }

  isState(state) {
    return this._stack.length > 0 && this._stack[this._stack.length - 1] === state;
  }
}

export class BlockParser {
  constructor(md) {
    this.blockprocessors = null;   // Registry, assigned by the builder
    this.state = new State();
    this.md = md;
    this.root = null;
  }

  parseDocument(lines) {
    this.root = new Element(this.md.docTag);
    this.parseChunk(this.root, lines.join('\n'));
    return this.root;
  }

  /** Split `text` on blank lines and parse the resulting blocks. */
  parseChunk(parent, text) {
    this.parseBlocks(parent, text.split('\n\n'));
  }

  parseBlocks(parent, blocks) {
    while (blocks.length) {
      for (const processor of this.blockprocessors) {
        if (processor.test(parent, blocks[0])) {
          if (processor.run(parent, blocks) !== false) break;
        }
      }
    }
  }
}

