// Explicit scanners for the block-level shapes.
//
// Each function walks characters and returns either `null` or a small record of
// span offsets. Where the reference grammar relies on backtracking (greedy runs
// that must give characters back for a later part to fit) the scanner does the
// same, trying candidate lengths from longest to shortest, so quirky inputs
// resolve the same way.

import { isDigit, isSpaceChar, leadingSpaces, pyStrip } from './chars.mjs';

/** `$` in multiline mode: end of string, or positioned on a newline. */
function atLineEnd(text, i) {
  return i >= text.length || text[i] === '\n';
}

/** Offsets of every position that begins a line. */
export function lineStarts(text) {
  const out = [0];
  for (let i = 0; i < text.length; i++) if (text[i] === '\n') out.push(i + 1);
  return out;
}

function runOf(text, i, ch) {
  let n = 0;
  while (i + n < text.length && text[i + n] === ch) n++;
  return n;
}

// ---------------------------------------------------------------------------
// ATX headers:  (start-of-block | newline) 1-6 '#'  content  trailing '#'*  EOL
// The content run may span newlines, and closing hashes are only stripped when
// what follows them ends the line. Both quantifiers give ground as needed.
// ---------------------------------------------------------------------------

export function matchHashHeader(block) {
  // The leading anchor is either start-of-string or a literal newline; there is
  // no multiline flag, so `^` only ever applies at offset 0.
  const candidates = [{ matchStart: 0, hashStart: 0 }];
  for (let i = 0; i < block.length; i++) {
    if (block[i] === '\n') candidates.push({ matchStart: i, hashStart: i + 1 });
  }

  for (const { matchStart, hashStart } of candidates) {
    const available = runOf(block, hashStart, '#');
    if (available === 0) continue;
    for (let level = Math.min(available, 6); level >= 1; level--) {
      const bodyStart = hashStart + level;
      // Lazily grow the content run; a unit is an escape pair or any single
      // non-backslash character (newlines included).
      let pos = bodyStart;
      for (;;) {
        const hashes = runOf(block, pos, '#');
        for (let h = hashes; h >= 0; h--) {
          const after = pos + h;
          if (after >= block.length) {
            return { start: matchStart, end: after, level, header: block.slice(bodyStart, pos) };
          }
          if (block[after] === '\n') {
            return { start: matchStart, end: after + 1, level, header: block.slice(bodyStart, pos) };
          }
        }
        if (pos >= block.length) break;
        // Grow by one unit and retry.
        if (block[pos] === '\\') {
          if (pos + 1 < block.length && block[pos + 1] !== '\n') pos += 2;
          else break;   // a trailing backslash matches neither alternative
        } else {
          pos += 1;
        }
      }
    }
  }
  return null;
}

// ---------------------------------------------------------------------------
// Setext headers: a first line, then a line of only '=' and/or '-'.
// Anchored at the start of the block.
// ---------------------------------------------------------------------------

export function matchSetextHeader(block) {
  const nl = block.indexOf('\n');
  if (nl === -1) return null;
  let i = nl + 1;
  const runStart = i;
  while (i < block.length && (block[i] === '=' || block[i] === '-')) i++;
  if (i === runStart) return null;
  while (i < block.length && block[i] === ' ') i++;
  if (!atLineEnd(block, i)) return null;
  return { level: block[runStart] === '=' ? 1 : 2 };
}

// ---------------------------------------------------------------------------
// Horizontal rules: up to 3 leading spaces, then at least three groups of
// "one-or-more rule characters followed by up to two spaces", then only spaces
// to end of line.
//
// The reference grammar wraps the repetition in a simulated atomic group, so
// once the repetition has settled on a division of the characters it cannot
// re-divide them to help the trailing "spaces only" check succeed. The scanner
// reproduces that by resolving the repetition first, in the same
// longest-run-first order, and only then testing the tail.
// ---------------------------------------------------------------------------

const RULE_CHARS = ['-', '_', '*'];

function scanRuleGroups(line, i, ch, reps) {
  const maxRun = runOf(line, i, ch);
  for (let run = maxRun; run >= 1; run--) {
    const afterRun = i + run;
    let spaces = 0;
    while (spaces < 2 && line[afterRun + spaces] === ' ') spaces++;
    for (let sp = spaces; sp >= 0; sp--) {
      const end = scanRuleGroups(line, afterRun + sp, ch, reps + 1);
      if (end !== -1) return end;
    }
  }
  return reps >= 3 ? i : -1;
}

export function matchHorizontalRule(block) {
  for (const start of lineStarts(block)) {
    let lineEnd = block.indexOf('\n', start);
    if (lineEnd === -1) lineEnd = block.length;
    const line = block.slice(start, lineEnd);
    const indent = Math.min(3, leadingSpaces(line));
    for (let k = indent; k >= 0; k--) {
      for (const ch of RULE_CHARS) {
        const end = scanRuleGroups(line, k, ch, 0);
        if (end === -1) continue;
        let t = end;
        while (t < line.length && line[t] === ' ') t++;
        if (t === line.length) {
          return { start, end: start + line.length };
        }
      }
    }
  }
  return null;
}

// ---------------------------------------------------------------------------
// Blockquotes: (start | newline) up to 3 spaces, '>', one optional space.
// ---------------------------------------------------------------------------

export function matchBlockQuote(block, from = 0) {
  for (let p = from; p <= block.length; p++) {
    const isAnchor = p === from ? (from === 0 || block[from - 1] === '\n') : block[p - 1] === '\n';
    if (!isAnchor) continue;
    let i = p;
    let spaces = 0;
    while (spaces < 3 && block[i] === ' ') { i++; spaces++; }
    if (block[i] !== '>') continue;
    i++;
    if (block[i] === ' ') i++;
    let lineEnd = block.indexOf('\n', i);
    if (lineEnd === -1) lineEnd = block.length;
    return { start: p, contentStart: i, contentEnd: lineEnd };
  }
  return null;
}

/** Strip one level of `>` quoting from a single line. */
export function cleanQuoteLine(line) {
  if (pyStrip(line) === '>') return '';
  let i = 0;
  let spaces = 0;
  while (spaces < 3 && line[i] === ' ') { i++; spaces++; }
  if (line[i] !== '>') return line;
  i++;
  if (line[i] === ' ') i++;
  return line.slice(i);
}

// ---------------------------------------------------------------------------
// List items.
//
//   item      up to (tab-1) spaces, marker, one-or-more spaces, content
//   child     same, but either marker family (used to split a block into items)
//   indent    tab..(2*tab - 1) spaces, then a marker (a nested item)
// ---------------------------------------------------------------------------

function scanMarker(line, i, kind) {
  // kind: 'o' = ordered only, 'u' = unordered only, 'either'
  if (kind !== 'u') {
    let j = i;
    while (j < line.length && isDigit(line[j])) j++;
    if (j > i && line[j] === '.') {
      return { end: j + 1, ordered: true, number: line.slice(i, j) };
    }
  }
  if (kind !== 'o') {
    const ch = line[i];
    if (ch === '*' || ch === '+' || ch === '-') {
      return { end: i + 1, ordered: false, number: null };
    }
  }
  return null;
}

/** An item line for a list of the given family, with at most `tab-1` indent. */
export function matchListItem(line, tabLength, kind) {
  const indent = leadingSpaces(line);
  if (indent > tabLength - 1) return null;
  const m = scanMarker(line, indent, kind);
  if (!m) return null;
  let i = m.end;
  const spaceStart = i;
  while (i < line.length && line[i] === ' ') i++;
  if (i === spaceStart) return null;          // marker must be followed by a space
  return { content: line.slice(i), ordered: m.ordered, number: m.number };
}

/** An item line of either family — how a block is divided into items. */
export function matchChildItem(line, tabLength) {
  return matchListItem(line, tabLength, 'either');
}

/** A line indented enough to belong to a nested list. */
export function matchIndentedItem(line, tabLength) {
  const indent = leadingSpaces(line);
  if (indent < tabLength || indent > tabLength * 2 - 1) return false;
  const m = scanMarker(line, indent, 'either');
  if (!m) return false;
  let i = m.end;
  const spaceStart = i;
  while (i < line.length && line[i] === ' ') i++;
  return i > spaceStart;
}

// ---------------------------------------------------------------------------
// Link reference definitions:
//
//   [id]: url "title"
//
// The url may sit on the line after the colon, and the title on the line after
// the url. Title delimiters are matching quotes or parentheses.
// ---------------------------------------------------------------------------

export function matchReference(block) {
  for (const start of lineStarts(block)) {
    let i = start;
    let spaces = 0;
    while (spaces < 3 && block[i] === ' ') { i++; spaces++; }
    if (block[i] !== '[') continue;
    i++;
    const idStart = i;
    while (i < block.length && block[i] !== '[' && block[i] !== ']') i++;
    if (block[i] !== ']') continue;
    const id = block.slice(idStart, i);
    i++;
    if (block[i] !== ':') continue;
    i++;

    // [ ]* \n? [ ]*
    while (block[i] === ' ') i++;
    if (block[i] === '\n') i++;
    while (block[i] === ' ') i++;

    // The url is a run of non-whitespace; it may have to give characters back
    // for the optional title and the end-of-line anchor to fit.
    const urlStart = i;
    let urlMax = i;
    while (urlMax < block.length && !isSpaceChar(block[urlMax])) urlMax++;
    if (urlMax === urlStart) continue;

    let matched = null;
    for (let urlEnd = urlMax; urlEnd > urlStart; urlEnd--) {
      const rest = tryReferenceTail(block, urlEnd);
      if (rest) {
        matched = { id, url: block.slice(urlStart, urlEnd), title: rest.title, end: rest.end };
        break;
      }
    }
    if (!matched) continue;
    return { start, end: matched.end, id: matched.id, url: matched.url, title: matched.title };
  }
  return null;
}

function tryReferenceTail(block, i) {
  let p = i;
  while (block[p] === ' ') p++;
  const afterSpaces = p;
  if (block[p] === '\n') {
    p++;
    while (block[p] === ' ') p++;
  }

  // With a title.
  const withTitle = scanTitle(block, p);
  if (withTitle) return withTitle;
  // Without a title: the optional newline must not have been consumed, since
  // the anchor has to land on the same logical line.
  if (atLineEnd(block, afterSpaces)) return { title: null, end: afterSpaces };
  return null;
}

function scanTitle(block, p) {
  const open = block[p];
  if (open === '"' || open === "'") {
    // Greedy inner run: prefer the last matching quote that leaves only spaces.
    for (let close = lastIndexOfBefore(block, open, p + 1); close > p; close = lastIndexOfBefore(block, open, p + 1, close - 1)) {
      let t = close + 1;
      while (block[t] === ' ') t++;
      if (atLineEnd(block, t)) return { title: block.slice(p + 1, close), end: t };
      if (close <= p + 1) break;
    }
    return null;
  }
  if (open === '(') {
    for (let close = lastIndexOfBefore(block, ')', p + 1); close > p; close = lastIndexOfBefore(block, ')', p + 1, close - 1)) {
      let t = close + 1;
      while (block[t] === ' ') t++;
      if (atLineEnd(block, t)) return { title: block.slice(p + 1, close), end: t };
      if (close <= p + 1) break;
    }
    return null;
  }
  return null;
}

/**
 * Last index of `ch` at or after `from` but still on the same line, at or
 * before `limit`. Returns -1 when there is none.
 */
function lastIndexOfBefore(text, ch, from, limit = Infinity) {
  let end = text.indexOf('\n', from);
  if (end === -1) end = text.length;
  const stop = Math.min(end - 1, limit);
  for (let i = stop; i >= from; i--) if (text[i] === ch) return i;
  return -1;
}

