// Explicit scanners for the block-level shapes.
//
// Each function walks characters and returns either `null` or a small record of
// span offsets. Where the reference grammar relies on backtracking (greedy runs
// that must give characters back for a later part to fit) the scanner does the
// same, trying candidate lengths from longest to shortest, so quirky inputs
// resolve the same way.

import { isDigit, isSpaceChar, leadingSpaces, pyStrip } from './chars.mjs';

/** `$` in multiline mode: end of string, or positioned on a newline. */
function atLineEnd(text, i) {
  return i >= text.length || text[i] === '\n';
}

/** Offsets of every position that begins a line. */
export function lineStarts(text) {
  const out = [0];
  for (let i = 0; i < text.length; i++) if (text[i] === '\n') out.push(i + 1);
  return out;
}

function runOf(text, i, ch) {
  let n = 0;
  while (i + n < text.length && text[i + n] === ch) n++;
  return n;
}

// ---------------------------------------------------------------------------
// ATX headers:  (start-of-block | newline) 1-6 '#'  content  trailing '#'*  EOL
// The content run may span newlines, and closing hashes are only stripped when
// what follows them ends the line. Both quantifiers give ground as needed.
// ---------------------------------------------------------------------------

export function matchHashHeader(block) {
  // The leading anchor is either start-of-string or a literal newline; there is
  // no multiline flag, so `^` only ever applies at offset 0.
  const candidates = [{ matchStart: 0, hashStart: 0 }];
  for (let i = 0; i < block.length; i++) {
    if (block[i] === '\n') candidates.push({ matchStart: i, hashStart: i + 1 });
  }

  for (const { matchStart, hashStart } of candidates) {
    const available = runOf(block, hashStart, '#');
    if (available === 0) continue;
    for (let level = Math.min(available, 6); level >= 1; level--) {
      const bodyStart = hashStart + level;
      // Lazily grow the content run; a unit is an escape pair or any single
      // non-backslash character (newlines included).
      let pos = bodyStart;
      for (;;) {
        const hashes = runOf(block, pos, '#');
        for (let h = hashes; h >= 0; h--) {
          const after = pos + h;
          if (after >= block.length) {
            return { start: matchStart, end: after, level, header: block.slice(bodyStart, pos) };
          }
          if (block[after] === '\n') {
            return { start: matchStart, end: after + 1, level, header: block.slice(bodyStart, pos) };
          }
        }
        if (pos >= block.length) break;
        // Grow by one unit and retry.
        if (block[pos] === '\\') {
          if (pos + 1 < block.length && block[pos + 1] !== '\n') pos += 2;
          else break;   // a trailing backslash matches neither alternative
        } else {
          pos += 1;
        }
      }
    }
  }
  return null;
}

// ---------------------------------------------------------------------------
// Setext headers: a first line, then a line of only '=' and/or '-'.
// Anchored at the start of the block.
// ---------------------------------------------------------------------------

export function matchSetextHeader(block) {
  const nl = block.indexOf('\n');
  if (nl === -1) return null;
  let i = nl + 1;
  const runStart = i;
  while (i < block.length && (block[i] === '=' || block[i] === '-')) i++;
  if (i === runStart) return null;
  while (i < block.length && block[i] === ' ') i++;
  if (!atLineEnd(block, i)) return null;
  return { level: block[runStart] === '=' ? 1 : 2 };
}

// ---------------------------------------------------------------------------
// Horizontal rules: up to 3 leading spaces, then at least three groups of
// "one-or-more rule characters followed by up to two spaces", then only spaces
// to end of line.
//
// The reference grammar wraps the repetition in a simulated atomic group, so
// once the repetition has settled on a division of the characters it cannot
// re-divide them to help the trailing "spaces only" check succeed. The scanner
// reproduces that by resolving the repetition first, in the same
// longest-run-first order, and only then testing the tail.
// ---------------------------------------------------------------------------

const RULE_CHARS = ['-', '_', '*'];

function scanRuleGroups(line, i, ch, reps) {
  const maxRun = runOf(line, i, ch);
  for (let run = maxRun; run >= 1; run--) {
    const afterRun = i + run;
    let spaces = 0;
    while (spaces < 2 && line[afterRun + spaces] === ' ') spaces++;
    for (let sp = spaces; sp >= 0; sp--) {
      const end = scanRuleGroups(line, afterRun + sp, ch, reps + 1);
      if (end !== -1) return end;
    }
  }
  return reps >= 3 ? i : -1;
}

export function matchHorizontalRule(block) {
  for (const start of lineStarts(block)) {
    let lineEnd = block.indexOf('\n', start);
    if (lineEnd === -1) lineEnd = block.length;
    const line = block.slice(start, lineEnd);
    const indent = Math.min(3, leadingSpaces(line));
    for (let k = indent; k >= 0; k--) {
      for (const ch of RULE_CHARS) {
        const end = scanRuleGroups(line, k, ch, 0);
        if (end === -1) continue;
        let t = end;
        while (t < line.length && line[t] === ' ') t++;
        if (t === line.length) {
          return { start, end: start + line.length };
        }
      }
    }
  }
  return null;
}

// ---------------------------------------------------------------------------
// Blockquotes: (start | newline) up to 3 spaces, '>', one optional space.
// ---------------------------------------------------------------------------

export function matchBlockQuote(block, from = 0) {
  for (let p = from; p <= block.length; p++) {
    const isAnchor = p === from ? (from === 0 || block[from - 1] === '\n') : block[p - 1] === '\n';
    if (!isAnchor) continue;
    let i = p;
    let spaces = 0;
    while (spaces < 3 && block[i] === ' ') { i++; spaces++; }
    if (block[i] !== '>') continue;
    i++;
    if (block[i] === ' ') i++;
    let lineEnd = block.indexOf('\n', i);
    if (lineEnd === -1) lineEnd = block.length;
    return { start: p, contentStart: i, contentEnd: lineEnd };
  }
  return null;
}

/** Strip one level of `>` quoting from a single line. */
export function cleanQuoteLine(line) {
  if (pyStrip(line) === '>') return '';
  let i = 0;
  let spaces = 0;
  while (spaces < 3 && line[i] === ' ') { i++; spaces++; }
  if (line[i] !== '>') return line;
  i++;
  if (line[i] === ' ') i++;
  return line.slice(i);
}

// ---------------------------------------------------------------------------
// List items.
//
//   item      up to (tab-1) spaces, marker, one-or-more spaces, content
//   child     same, but either marker family (used to split a block into items)
//   indent    tab..(2*tab - 1) spaces, then a marker (a nested item)
// ---------------------------------------------------------------------------

function scanMarker(line, i, kind) {
  // kind: 'o' = ordered only, 'u' = unordered only, 'either'
  if (kind !== 'u') {
    let j = i;
    while (j < line.length && isDigit(line[j])) j++;
    if (j > i && line[j] === '.') {
      return { end: j + 1, ordered: true, number: line.slice(i, j) };
    }
  }
  if (kind !== 'o') {
    const ch = line[i];
    if (ch === '*' || ch === '+' || ch === '-') {
      return { end: i + 1, ordered: false, number: null };
    }
  }
  return null;
}

/** An item line for a list of the given family, with at most `tab-1` indent. */
export function matchListItem(line, tabLength, kind) {
  const indent = leadingSpaces(line);
  if (indent > tabLength - 1) return null;
  const m = scanMarker(line, indent, kind);
  if (!m) return null;
  let i = m.end;
  const spaceStart = i;
  while (i < line.length && line[i] === ' ') i++;
  if (i === spaceStart) return null;          // marker must be followed by a space
  return { content: line.slice(i), ordered: m.ordered, number: m.number };
}

/** An item line of either family — how a block is divided into items. */
export function matchChildItem(line, tabLength) {
  return matchListItem(line, tabLength, 'either');
}

/** A line indented enough to belong to a nested list. */
export function matchIndentedItem(line, tabLength) {
  const indent = leadingSpaces(line);
  if (indent < tabLength || indent > tabLength * 2 - 1) return false;
  const m = scanMarker(line, indent, 'either');
  if (!m) return false;
  let i = m.end;
  const spaceStart = i;
  while (i < line.length && line[i] === ' ') i++;
  return i > spaceStart;
}

// ---------------------------------------------------------------------------
// Link reference definitions:
//
//   [id]: url "title"
//
// The url may sit on the line after the colon, and the title on the line after
// the url. Title delimiters are matching quotes or parentheses.
// ---------------------------------------------------------------------------

export function matchReference(block) {
  for (const start of lineStarts(block)) {
    let i = start;
    let spaces = 0;
    while (spaces < 3 && block[i] === ' ') { i++; spaces++; }
    if (block[i] !== '[') continue;
    i++;
    const idStart = i;
    while (i < block.length && block[i] !== '[' && block[i] !== ']') i++;
    if (block[i] !== ']') continue;
    const id = block.slice(idStart, i);
    i++;
    if (block[i] !== ':') continue;
    i++;

    // [ ]* \n? [ ]*
    while (block[i] === ' ') i++;
    if (block[i] === '\n') i++;
    while (block[i] === ' ') i++;

    // The url is a run of non-whitespace; it may have to give characters back
    // for the optional title and the end-of-line anchor to fit.
    const urlStart = i;
    let urlMax = i;
    while (urlMax < block.length && !isSpaceChar(block[urlMax])) urlMax++;
    if (urlMax === urlStart) continue;

    let matched = null;
    for (let urlEnd = urlMax; urlEnd > urlStart; urlEnd--) {
      const rest = tryReferenceTail(block, urlEnd);
      if (rest) {
        matched = { id, url: block.slice(urlStart, urlEnd), title: rest.title, end: rest.end };
        break;
      }
    }
    if (!matched) continue;
    return { start, end: matched.end, id: matched.id, url: matched.url, title: matched.title };
  }
  return null;
}

function tryReferenceTail(block, i) {
  let p = i;
  while (block[p] === ' ') p++;
  const afterSpaces = p;
  if (block[p] === '\n') {
    p++;
    while (block[p] === ' ') p++;
  }

  // With a title.
  const withTitle = scanTitle(block, p);
  if (withTitle) return withTitle;
  // Without a title: the optional newline must not have been consumed, since
  // the anchor has to land on the same logical line.
  if (atLineEnd(block, afterSpaces)) return { title: null, end: afterSpaces };
  return null;
}

function scanTitle(block, p) {
  const open = block[p];
  if (open === '"' || open === "'") {
    // Greedy inner run: prefer the last matching quote that leaves only spaces.
    for (let close = lastIndexOfBefore(block, open, p + 1); close > p; close = lastIndexOfBefore(block, open, p + 1, close - 1)) {
      let t = close + 1;
      while (block[t] === ' ') t++;
      if (atLineEnd(block, t)) return { title: block.slice(p + 1, close), end: t };
      if (close <= p + 1) break;
    }
    return null;
  }
  if (open === '(') {
    for (let close = lastIndexOfBefore(block, ')', p + 1); close > p; close = lastIndexOfBefore(block, ')', p + 1, close - 1)) {
      let t = close + 1;
      while (block[t] === ' ') t++;
      if (atLineEnd(block, t)) return { title: block.slice(p + 1, close), end: t };
      if (close <= p + 1) break;
    }
    return null;
  }
  return null;
}

/**
 * Last index of `ch` at or after `from` but still on the same line, at or
 * before `limit`. Returns -1 when there is none.
 */
function lastIndexOfBefore(text, ch, from, limit = Infinity) {
  let end = text.indexOf('\n', from);
  if (end === -1) end = text.length;
  const stop = Math.min(end - 1, limit);
  for (let i = stop; i >= from; i--) if (text[i] === ch) return i;
  return -1;
}

input.content:
// The block processors, in priority order.
//
// Each processor exposes `test(parent, block)` and `run(parent, blocks)`.
// `run` may mutate the queue: pushing text back onto the front defers it, which
// is how a block containing several constructs gets peeled apart one at a time.

import { Element, subElement } from './element.mjs';
import { codeEscape } from './serializer.mjs';
import {
  isBlankString, pyStrip, pyLStrip, rstripChars, lstripChars, leadingSpaces,
} from './chars.mjs';
import {
  matchHashHeader, matchSetextHeader, matchHorizontalRule, matchBlockQuote,
  cleanQuoteLine, matchListItem, matchChildItem, matchIndentedItem,
  matchReference,
} from './block-matchers.mjs';

class BlockProcessor {
  constructor(parser) {
    this.parser = parser;
    this.tabLength = parser.md.tabLength;
  }

  lastChild(parent) {
    return parent.length ? parent.at(-1) : null;
  }

  /**
   * Remove one indent level from the front of each line, stopping at the first
   * line that is neither indented nor blank. Returns the dedented text and
   * whatever was left behind.
   */
  detab(text, length = null) {
    const width = length === null ? this.tabLength : length;
    const pad = ' '.repeat(width);
    const lines = text.split('\n');
    const kept = [];
    let i = 0;
    for (; i < lines.length; i++) {
      const line = lines[i];
      if (line.startsWith(pad)) kept.push(line.slice(width));
      else if (isBlankString(line)) kept.push('');
      else break;
    }
    return [kept.join('\n'), lines.slice(i).join('\n')];
  }

  /** Remove `level` indent levels where present, tolerating dedented lines. */
  looseDetab(text, level = 1) {
    const width = this.tabLength * level;
    const pad = ' '.repeat(width);
    const lines = text.split('\n');
    for (let i = 0; i < lines.length; i++) {
      if (lines[i].startsWith(pad)) lines[i] = lines[i].slice(width);
    }
    return lines.join('\n');
  }
}

// ---------------------------------------------------------------------------

/**
 * Consumes blocks that are empty or begin with a blank line. When the previous
 * block was a code block the blank line is folded into it, since blank lines do
 * not terminate indented code.
 */
export class EmptyBlockProcessor extends BlockProcessor {
  test(parent, block) {
    return !block || block.startsWith('\n');
  }

  run(parent, blocks) {
    let block = blocks.shift();
    const filler = '\n\n';
    if (block) {
      block = block.slice(1);           // drop a single blank line
      if (block) blocks.unshift(block);
    }
    const sibling = this.lastChild(parent);
    if (sibling !== null && sibling.tag === 'pre' && sibling.length
        && sibling.at(0).tag === 'code') {
      const code = sibling.at(0);
      code.setAtomicText((code.text === null ? '' : code.text) + filler);
    }
  }
}

// ---------------------------------------------------------------------------

/**
 * Handles indented continuations inside list items: further paragraphs, code
 * blocks and nested lists that belong to the item above rather than to the
 * document.
 */
export class ListIndentProcessor extends BlockProcessor {
  constructor(parser) {
    super(parser);
    this.ITEM_TYPES = ['li'];
    this.LIST_TYPES = ['ul', 'ol'];
  }

  test(parent, block) {
    if (!block.startsWith(' '.repeat(this.tabLength))) return false;
    if (this.parser.state.isState('detabbed')) return false;
    if (this.ITEM_TYPES.includes(parent.tag)) return true;
    return parent.length > 0 && this.LIST_TYPES.includes(parent.at(-1).tag);
  }

  run(parent, blocks) {
    let block = blocks.shift();
    const [level, sibling] = this.getLevel(parent, block);
    block = this.looseDetab(block, level);

    this.parser.state.set('detabbed');
    if (this.ITEM_TYPES.includes(parent.tag)) {
      // An indented list whose first member was already consumed leaves a list
      // child on the item; that list, not the item, is the right parent.
      if (parent.length && this.LIST_TYPES.includes(parent.at(-1).tag)) {
        this.parser.parseBlocks(parent.at(-1), [block]);
      } else {
        this.parser.parseBlocks(parent, [block]);
      }
    } else if (this.ITEM_TYPES.includes(sibling.tag)) {
      this.parser.parseBlocks(sibling, [block]);
    } else if (sibling.length && this.ITEM_TYPES.includes(sibling.at(-1).tag)) {
      this.parser.parseBlocks(sibling.at(-1), [block]);
    } else {
      this.createItem(sibling, block);
    }
    this.parser.state.reset();
  }

  createItem(parent, block) {
    const li = subElement(parent, 'li');
    this.parser.parseBlocks(li, [block]);
  }

  /** Walk down the existing list structure to the depth this block indents to. */
  getLevel(parent, block) {
    const indent = leadingSpaces(block);
    const indentLevel = Math.floor(indent / this.tabLength);
    let level = this.parser.state.isState('list') ? 1 : 0;
    let node = parent;
    while (indentLevel > level) {
      const child = this.lastChild(node);
      if (child !== null
          && (this.LIST_TYPES.includes(child.tag) || this.ITEM_TYPES.includes(child.tag))) {
        if (this.LIST_TYPES.includes(child.tag)) level += 1;
        node = child;
      } else {
        break;   // no deeper list to attach to
      }
    }
    return [level, node];
  }
}

// ---------------------------------------------------------------------------

/** Indented code blocks. Consecutive blocks merge into one `<pre><code>`. */
export class CodeBlockProcessor extends BlockProcessor {
  test(parent, block) {
    return block.startsWith(' '.repeat(this.tabLength));
  }

  run(parent, blocks) {
    const sibling = this.lastChild(parent);
    let block = blocks.shift();
    let theRest = '';
    if (sibling !== null && sibling.tag === 'pre' && sibling.length
        && sibling.at(0).tag === 'code') {
      // Blank lines do not break indented code, so append to the block above.
      const code = sibling.at(0);
      [block, theRest] = this.detab(block);
      code.setAtomicText(code.text + '\n' + codeEscape(rstripChars(block, ' \t\n')) + '\n');
    } else {
      const pre = subElement(parent, 'pre');
      const code = subElement(pre, 'code');
      [block, theRest] = this.detab(block);
      code.setAtomicText(codeEscape(rstripChars(block, ' \t\n')) + '\n');
    }
    if (theRest) blocks.unshift(theRest);
  }
}

// ---------------------------------------------------------------------------

export class HashHeaderProcessor extends BlockProcessor {
  test(parent, block) {
    return matchHashHeader(block) !== null;
  }

  run(parent, blocks) {
    const block = blocks.shift();
    const m = matchHashHeader(block);
    if (m === null) return;
    const before = block.slice(0, m.start);
    const after = block.slice(m.end);
    if (before) this.parser.parseBlocks(parent, [before]);
    const h = subElement(parent, 'h' + m.level);
    h.text = pyStrip(m.header);
    if (after) blocks.unshift(after);
  }
}

// ---------------------------------------------------------------------------

export class SetextHeaderProcessor extends BlockProcessor {
  test(parent, block) {
    return matchSetextHeader(block) !== null;
  }

  run(parent, blocks) {
    const lines = blocks.shift().split('\n');
    const level = lines[1].startsWith('=') ? 1 : 2;
    const h = subElement(parent, 'h' + level);
    h.text = pyStrip(lines[0]);
    if (lines.length > 2) blocks.unshift(lines.slice(2).join('\n'));
  }
}

// ---------------------------------------------------------------------------

export class HRProcessor extends BlockProcessor {
  test(parent, block) {
    this.match = matchHorizontalRule(block);
    return this.match !== null;
  }

  run(parent, blocks) {
    const block = blocks.shift();
    const prelines = rstripChars(block.slice(0, this.match.start), '\n');
    if (prelines) this.parser.parseBlocks(parent, [prelines]);
    subElement(parent, 'hr');
    const postlines = lstripChars(block.slice(this.match.end), '\n');
    if (postlines) blocks.unshift(postlines);
  }
}

// ---------------------------------------------------------------------------

/**
 * Ordered lists. Also the base for unordered lists, which differ only in the
 * marker and the wrapping tag.
 */
export class OListProcessor extends BlockProcessor {
  constructor(parser) {
    super(parser);
    this.TAG = 'ol';
    this.KIND = 'o';
    this.STARTSWITH = '1';
    this.LAZY_OL = true;
    this.SIBLING_TAGS = ['ol', 'ul'];
  }

  test(parent, block) {
    return matchListItem(block.split('\n')[0], this.tabLength, this.KIND) !== null
      && matchListItem(block, this.tabLength, this.KIND) !== null;
  }

  run(parent, blocks) {
    const items = this.getItems(blocks.shift());
    const sibling = this.lastChild(parent);
    let lst;

    if (sibling !== null && this.SIBLING_TAGS.includes(sibling.tag)) {
      // Continuing a list that a blank line interrupted: the items on either
      // side of the gap become loose, so the previous item's bare text has to
      // move into a paragraph of its own.
      lst = sibling;
      const last = lst.at(-1);
      if (last.text) {
        const p = new Element('p');
        p.text = last.text;
        last.text = '';
        last.insert(0, p);
      }
      const lch = this.lastChild(last);
      if (lch !== null && lch.tail) {
        const p = subElement(last, 'p');
        p.text = pyLStrip(lch.tail);
        lch.tail = '';
      }

      const li = subElement(lst, 'li');
      this.parser.state.set('looselist');
      const firstItem = items.shift();
      this.parser.parseBlocks(li, [firstItem]);
      this.parser.state.reset();
    } else if (parent.tag === 'ol' || parent.tag === 'ul') {
      // A multi-item nested list whose first item sat in an empty parent item.
      lst = parent;
    } else {
      lst = subElement(parent, this.TAG);
      if (!this.LAZY_OL && this.STARTSWITH !== '1') lst.set('start', this.STARTSWITH);
    }

    this.parser.state.set('list');
    for (const item of items) {
      if (item.startsWith(' '.repeat(this.tabLength))) {
        this.parser.parseBlocks(lst.at(-1), [item]);
      } else {
        const li = subElement(lst, 'li');
        this.parser.parseBlocks(li, [item]);
      }
    }
    this.parser.state.reset();
  }

  /** Divide a block into item texts. */
  getItems(block) {
    const items = [];
    for (const line of block.split('\n')) {
      const m = matchChildItem(line, this.tabLength);
      if (m) {
        if (items.length === 0 && this.TAG === 'ol' && m.number !== null) {
          this.STARTSWITH = m.number;
        }
        items.push(m.content);
      } else if (matchIndentedItem(line, this.tabLength)) {
        if (items.length && items[items.length - 1].startsWith(' '.repeat(this.tabLength))) {
          items[items.length - 1] = items[items.length - 1] + '\n' + line;
        } else {
          items.push(line);
        }
      } else if (items.length) {
        items[items.length - 1] = items[items.length - 1] + '\n' + line;
      } else {
        items.push(line);
      }
    }
    return items;
  }
}

export class UListProcessor extends OListProcessor {
  constructor(parser) {
    super(parser);
    this.TAG = 'ul';
    this.KIND = 'u';
  }
}

// ---------------------------------------------------------------------------

export class BlockQuoteProcessor extends BlockProcessor {
  test(parent, block) {
    return matchBlockQuote(block) !== null;
  }

  run(parent, blocks) {
    let block = blocks.shift();
    const m = matchBlockQuote(block);
    if (m) {
      const before = block.slice(0, m.start);
      this.parser.parseBlocks(parent, [before]);
      block = block.slice(m.start).split('\n').map(cleanQuoteLine).join('\n');
    }
    const sibling = this.lastChild(parent);
    const quote = (sibling !== null && sibling.tag === 'blockquote')
      ? sibling
      : subElement(parent, 'blockquote');
    // The state change makes quoted content inside a list use paragraphs.
    this.parser.state.set('blockquote');
    this.parser.parseBlocks(quote, [block]);
    this.parser.state.reset();
  }
}

// ---------------------------------------------------------------------------

/** Collects `[id]: url "title"` definitions; they produce no output. */
export class ReferenceProcessor extends BlockProcessor {
  test(parent, block) {
    return true;
  }

  run(parent, blocks) {
    const block = blocks.shift();
    const m = matchReference(block);
    if (m) {
      const id = pyStrip(m.id).toLowerCase();
      const link = rstripChars(lstripChars(m.url, '<'), '>');
      this.parser.md.references.set(id, [link, m.title === undefined ? null : m.title]);
      const after = block.slice(m.end);
      if (pyStrip(after)) blocks.unshift(lstripChars(after, '\n'));
      const before = block.slice(0, m.start);
      if (pyStrip(before)) blocks.unshift(rstripChars(before, '\n'));
      return true;
    }
    blocks.unshift(block);
    return false;
  }
}

// ---------------------------------------------------------------------------

/** Last resort: everything else becomes a paragraph. */
export class ParagraphProcessor extends BlockProcessor {
  test(parent, block) {
    return true;
  }

  run(parent, blocks) {
    const block = blocks.shift();
    if (!pyStrip(block)) return;

    if (this.parser.state.isState('list')) {
      // A tight list item: the text belongs directly to the item, not to a
      // paragraph. Reached when e.g. a header inside an item is not followed
      // by a blank line.
      if (parent.length) {
        const sibling = this.lastChild(parent);
        sibling.tail = sibling.tail ? sibling.tail + '\n' + block : '\n' + block;
      } else if (parent.text) {
        parent.text = parent.text + '\n' + block;
      } else {
        parent.text = pyLStrip(block);
      }
    } else {
      const p = subElement(parent, 'p');
      p.text = pyLStrip(block);
    }
  }
}

// ---------------------------------------------------------------------------

export function buildBlockParser(md, BlockParser, Registry) {
  const parser = new BlockParser(md);
  const reg = new Registry();
  reg.register(new EmptyBlockProcessor(parser), 'empty', 100);
  reg.register(new ListIndentProcessor(parser), 'indent', 90);
  reg.register(new CodeBlockProcessor(parser), 'code', 80);
  reg.register(new HashHeaderProcessor(parser), 'hashheader', 70);
  reg.register(new SetextHeaderProcessor(parser), 'setextheader', 60);
  reg.register(new HRProcessor(parser), 'hr', 50);
  reg.register(new OListProcessor(parser), 'olist', 40);
  reg.register(new UListProcessor(parser), 'ulist', 30);
  reg.register(new BlockQuoteProcessor(parser), 'quote', 20);
  reg.register(new ReferenceProcessor(parser), 'reference', 15);
  reg.register(new ParagraphProcessor(parser), 'paragraph', 10);
  parser.blockprocessors = reg;
  return parser;
}

