// The block processors, in priority order.
//
// Each processor exposes `test(parent, block)` and `run(parent, blocks)`.
// `run` may mutate the queue: pushing text back onto the front defers it, which
// is how a block containing several constructs gets peeled apart one at a time.

import { Element, subElement } from './element.mjs';
import { codeEscape } from './serializer.mjs';
import {
  isBlankString, pyStrip, pyLStrip, rstripChars, lstripChars, leadingSpaces,
} from './chars.mjs';
import {
  matchHashHeader, matchSetextHeader, matchHorizontalRule, matchBlockQuote,
  cleanQuoteLine, matchListItem, matchChildItem, matchIndentedItem,
  matchReference,
} from './block-matchers.mjs';

class BlockProcessor {
  constructor(parser) {
    this.parser = parser;
    this.tabLength = parser.md.tabLength;
  }

  lastChild(parent) {
    return parent.length ? parent.at(-1) : null;
  }

  /**
   * Remove one indent level from the front of each line, stopping at the first
   * line that is neither indented nor blank. Returns the dedented text and
   * whatever was left behind.
   */
  detab(text, length = null) {
    const width = length === null ? this.tabLength : length;
    const pad = ' '.repeat(width);
    const lines = text.split('\n');
    const kept = [];
    let i = 0;
    for (; i < lines.length; i++) {
      const line = lines[i];
      if (line.startsWith(pad)) kept.push(line.slice(width));
      else if (isBlankString(line)) kept.push('');
      else break;
    }
    return [kept.join('\n'), lines.slice(i).join('\n')];
  }

  /** Remove `level` indent levels where present, tolerating dedented lines. */
  looseDetab(text, level = 1) {
    const width = this.tabLength * level;
    const pad = ' '.repeat(width);
    const lines = text.split('\n');
    for (let i = 0; i < lines.length; i++) {
      if (lines[i].startsWith(pad)) lines[i] = lines[i].slice(width);
    }
    return lines.join('\n');
  }
}

// ---------------------------------------------------------------------------

/**
 * Consumes blocks that are empty or begin with a blank line. When the previous
 * block was a code block the blank line is folded into it, since blank lines do
 * not terminate indented code.
 */
export class EmptyBlockProcessor extends BlockProcessor {
  test(parent, block) {
    return !block || block.startsWith('\n');
  }

  run(parent, blocks) {
    let block = blocks.shift();
    const filler = '\n\n';
    if (block) {
      block = block.slice(1);           // drop a single blank line
      if (block) blocks.unshift(block);
    }
    const sibling = this.lastChild(parent);
    if (sibling !== null && sibling.tag === 'pre' && sibling.length
        && sibling.at(0).tag === 'code') {
      const code = sibling.at(0);
      code.setAtomicText((code.text === null ? '' : code.text) + filler);
    }
  }
}

// ---------------------------------------------------------------------------

/**
 * Handles indented continuations inside list items: further paragraphs, code
 * blocks and nested lists that belong to the item above rather than to the
 * document.
 */
export class ListIndentProcessor extends BlockProcessor {
  constructor(parser) {
    super(parser);
    this.ITEM_TYPES = ['li'];
    this.LIST_TYPES = ['ul', 'ol'];
  }

  test(parent, block) {
    if (!block.startsWith(' '.repeat(this.tabLength))) return false;
    if (this.parser.state.isState('detabbed')) return false;
    if (this.ITEM_TYPES.includes(parent.tag)) return true;
    return parent.length > 0 && this.LIST_TYPES.includes(parent.at(-1).tag);
  }

  run(parent, blocks) {
    let block = blocks.shift();
    const [level, sibling] = this.getLevel(parent, block);
    block = this.looseDetab(block, level);

    this.parser.state.set('detabbed');
    if (this.ITEM_TYPES.includes(parent.tag)) {
      // An indented list whose first member was already consumed leaves a list
      // child on the item; that list, not the item, is the right parent.
      if (parent.length && this.LIST_TYPES.includes(parent.at(-1).tag)) {
        this.parser.parseBlocks(parent.at(-1), [block]);
      } else {
        this.parser.parseBlocks(parent, [block]);
      }
    } else if (this.ITEM_TYPES.includes(sibling.tag)) {
      this.parser.parseBlocks(sibling, [block]);
    } else if (sibling.length && this.ITEM_TYPES.includes(sibling.at(-1).tag)) {
      this.parser.parseBlocks(sibling.at(-1), [block]);
    } else {
      this.createItem(sibling, block);
    }
    this.parser.state.reset();
  }

  createItem(parent, block) {
    const li = subElement(parent, 'li');
    this.parser.parseBlocks(li, [block]);
  }

  /** Walk down the existing list structure to the depth this block indents to. */
  getLevel(parent, block) {
    const indent = leadingSpaces(block);
    const indentLevel = Math.floor(indent / this.tabLength);
    let level = this.parser.state.isState('list') ? 1 : 0;
    let node = parent;
    while (indentLevel > level) {
      const child = this.lastChild(node);
      if (child !== null
          && (this.LIST_TYPES.includes(child.tag) || this.ITEM_TYPES.includes(child.tag))) {
        if (this.LIST_TYPES.includes(child.tag)) level += 1;
        node = child;
      } else {
        break;   // no deeper list to attach to
      }
    }
    return [level, node];
  }
}

// ---------------------------------------------------------------------------

/** Indented code blocks. Consecutive blocks merge into one `<pre><code>`. */
export class CodeBlockProcessor extends BlockProcessor {
  test(parent, block) {
    return block.startsWith(' '.repeat(this.tabLength));
  }

  run(parent, blocks) {
    const sibling = this.lastChild(parent);
    let block = blocks.shift();
    let theRest = '';
    if (sibling !== null && sibling.tag === 'pre' && sibling.length
        && sibling.at(0).tag === 'code') {
      // Blank lines do not break indented code, so append to the block above.
      const code = sibling.at(0);
      [block, theRest] = this.detab(block);
      code.setAtomicText(code.text + '\n' + codeEscape(rstripChars(block, ' \t\n')) + '\n');
    } else {
      const pre = subElement(parent, 'pre');
      const code = subElement(pre, 'code');
      [block, theRest] = this.detab(block);
      code.setAtomicText(codeEscape(rstripChars(block, ' \t\n')) + '\n');
    }
    if (theRest) blocks.unshift(theRest);
  }
}

// ---------------------------------------------------------------------------

export class HashHeaderProcessor extends BlockProcessor {
  test(parent, block) {
    return matchHashHeader(block) !== null;
  }

  run(parent, blocks) {
    const block = blocks.shift();
    const m = matchHashHeader(block);
    if (m === null) return;
    const before = block.slice(0, m.start);
    const after = block.slice(m.end);
    if (before) this.parser.parseBlocks(parent, [before]);
    const h = subElement(parent, 'h' + m.level);
    h.text = pyStrip(m.header);
    if (after) blocks.unshift(after);
  }
}

// ---------------------------------------------------------------------------

export class SetextHeaderProcessor extends BlockProcessor {
  test(parent, block) {
    return matchSetextHeader(block) !== null;
  }

  run(parent, blocks) {
    const lines = blocks.shift().split('\n');
    const level = lines[1].startsWith('=') ? 1 : 2;
    const h = subElement(parent, 'h' + level);
    h.text = pyStrip(lines[0]);
    if (lines.length > 2) blocks.unshift(lines.slice(2).join('\n'));
  }
}

// ---------------------------------------------------------------------------

export class HRProcessor extends BlockProcessor {
  test(parent, block) {
    this.match = matchHorizontalRule(block);
    return this.match !== null;
  }

  run(parent, blocks) {
    const block = blocks.shift();
    const prelines = rstripChars(block.slice(0, this.match.start), '\n');
    if (prelines) this.parser.parseBlocks(parent, [prelines]);
    subElement(parent, 'hr');
    const postlines = lstripChars(block.slice(this.match.end), '\n');
    if (postlines) blocks.unshift(postlines);
  }
}

// ---------------------------------------------------------------------------

/**
 * Ordered lists. Also the base for unordered lists, which differ only in the
 * marker and the wrapping tag.
 */
export class OListProcessor extends BlockProcessor {
  constructor(parser) {
    super(parser);
    this.TAG = 'ol';
    this.KIND = 'o';
    this.STARTSWITH = '1';
    this.LAZY_OL = true;
    this.SIBLING_TAGS = ['ol', 'ul'];
  }

  test(parent, block) {
    return matchListItem(block.split('\n')[0], this.tabLength, this.KIND) !== null
      && matchListItem(block, this.tabLength, this.KIND) !== null;
  }

  run(parent, blocks) {
    const items = this.getItems(blocks.shift());
    const sibling = this.lastChild(parent);
    let lst;

    if (sibling !== null && this.SIBLING_TAGS.includes(sibling.tag)) {
      // Continuing a list that a blank line interrupted: the items on either
      // side of the gap become loose, so the previous item's bare text has to
      // move into a paragraph of its own.
      lst = sibling;
      const last = lst.at(-1);
      if (last.text) {
        const p = new Element('p');
        p.text = last.text;
        last.text = '';
        last.insert(0, p);
      }
      const lch = this.lastChild(last);
      if (lch !== null && lch.tail) {
        const p = subElement(last, 'p');
        p.text = pyLStrip(lch.tail);
        lch.tail = '';
      }

      const li = subElement(lst, 'li');
      this.parser.state.set('looselist');
      const firstItem = items.shift();
      this.parser.parseBlocks(li, [firstItem]);
      this.parser.state.reset();
    } else if (parent.tag === 'ol' || parent.tag === 'ul') {
      // A multi-item nested list whose first item sat in an empty parent item.
      lst = parent;
    } else {
      lst = subElement(parent, this.TAG);
      if (!this.LAZY_OL && this.STARTSWITH !== '1') lst.set('start', this.STARTSWITH);
    }

    this.parser.state.set('list');
    for (const item of items) {
      if (item.startsWith(' '.repeat(this.tabLength))) {
        this.parser.parseBlocks(lst.at(-1), [item]);
      } else {
        const li = subElement(lst, 'li');
        this.parser.parseBlocks(li, [item]);
      }
    }
    this.parser.state.reset();
  }

  /** Divide a block into item texts. */
  getItems(block) {
    const items = [];
    for (const line of block.split('\n')) {
      const m = matchChildItem(line, this.tabLength);
      if (m) {
        if (items.length === 0 && this.TAG === 'ol' && m.number !== null) {
          this.STARTSWITH = m.number;
        }
        items.push(m.content);
      } else if (matchIndentedItem(line, this.tabLength)) {
        if (items.length && items[items.length - 1].startsWith(' '.repeat(this.tabLength))) {
          items[items.length - 1] = items[items.length - 1] + '\n' + line;
        } else {
          items.push(line);
        }
      } else if (items.length) {
        items[items.length - 1] = items[items.length - 1] + '\n' + line;
      } else {
        items.push(line);
      }
    }
    return items;
  }
}

export class UListProcessor extends OListProcessor {
  constructor(parser) {
    super(parser);
    this.TAG = 'ul';
    this.KIND = 'u';
  }
}

// ---------------------------------------------------------------------------

export class BlockQuoteProcessor extends BlockProcessor {
  test(parent, block) {
    return matchBlockQuote(block) !== null;
  }

  run(parent, blocks) {
    let block = blocks.shift();
    const m = matchBlockQuote(block);
    if (m) {
      const before = block.slice(0, m.start);
      this.parser.parseBlocks(parent, [before]);
      block = block.slice(m.start).split('\n').map(cleanQuoteLine).join('\n');
    }
    const sibling = this.lastChild(parent);
    const quote = (sibling !== null && sibling.tag === 'blockquote')
      ? sibling
      : subElement(parent, 'blockquote');
    // The state change makes quoted content inside a list use paragraphs.
    this.parser.state.set('blockquote');
    this.parser.parseBlocks(quote, [block]);
    this.parser.state.reset();
  }
}

// ---------------------------------------------------------------------------

/** Collects `[id]: url "title"` definitions; they produce no output. */
export class ReferenceProcessor extends BlockProcessor {
  test(parent, block) {
    return true;
  }

  run(parent, blocks) {
    const block = blocks.shift();
    const m = matchReference(block);
    if (m) {
      const id = pyStrip(m.id).toLowerCase();
      const link = rstripChars(lstripChars(m.url, '<'), '>');
      this.parser.md.references.set(id, [link, m.title === undefined ? null : m.title]);
      const after = block.slice(m.end);
      if (pyStrip(after)) blocks.unshift(lstripChars(after, '\n'));
      const before = block.slice(0, m.start);
      if (pyStrip(before)) blocks.unshift(rstripChars(before, '\n'));
      return true;
    }
    blocks.unshift(block);
    return false;
  }
}

// ---------------------------------------------------------------------------

/** Last resort: everything else becomes a paragraph. */
export class ParagraphProcessor extends BlockProcessor {
  test(parent, block) {
    return true;
  }

  run(parent, blocks) {
    const block = blocks.shift();
    if (!pyStrip(block)) return;

    if (this.parser.state.isState('list')) {
      // A tight list item: the text belongs directly to the item, not to a
      // paragraph. Reached when e.g. a header inside an item is not followed
      // by a blank line.
      if (parent.length) {
        const sibling = this.lastChild(parent);
        sibling.tail = sibling.tail ? sibling.tail + '\n' + block : '\n' + block;
      } else if (parent.text) {
        parent.text = parent.text + '\n' + block;
      } else {
        parent.text = pyLStrip(block);
      }
    } else {
      const p = subElement(parent, 'p');
      p.text = pyLStrip(block);
    }
  }
}

// ---------------------------------------------------------------------------

export function buildBlockParser(md, BlockParser, Registry) {
  const parser = new BlockParser(md);
  const reg = new Registry();
  reg.register(new EmptyBlockProcessor(parser), 'empty', 100);
  reg.register(new ListIndentProcessor(parser), 'indent', 90);
  reg.register(new CodeBlockProcessor(parser), 'code', 80);
  reg.register(new HashHeaderProcessor(parser), 'hashheader', 70);
  reg.register(new SetextHeaderProcessor(parser), 'setextheader', 60);
  reg.register(new HRProcessor(parser), 'hr', 50);
  reg.register(new OListProcessor(parser), 'olist', 40);
  reg.register(new UListProcessor(parser), 'ulist', 30);
  reg.register(new BlockQuoteProcessor(parser), 'quote', 20);
  reg.register(new ReferenceProcessor(parser), 'reference', 15);
  reg.register(new ParagraphProcessor(parser), 'paragraph', 10);
  parser.blockprocessors = reg;
  return parser;
}

