// A small backtracking matcher over an explicitly constructed node tree.
//
// The inline grammar of Markdown leans on ordering subtleties — greedy runs that
// give characters back, lazy runs that stop at the first workable point,
// zero-width assertions that look at the neighbouring character — and getting
// those wrong changes the output. Rather than approximate each shape with ad-hoc
// index juggling, the grammar fragments are built as trees of the node
// constructors below and walked by `exec`, which explores alternatives in the
// same order the reference implementation's engine does.
//
// Node constructors: lit, cls, any, seq, alt, rep, group, ref, ahead, behind,
// bos, eos, bol, eol.
//
// Evaluation is continuation-passing: each node calls `k` with the position it
// reached, and a `-1` return means "that path failed, try the next alternative".

const FAIL = -1;

// --- node constructors -----------------------------------------------------

/** Literal text. */
export function lit(s) {
  return { t: 'lit', s };
}

/** Single character accepted by `test`. */
export function cls(test) {
  return { t: 'cls', test };
}

/** Single character rejected by `test`. */
export function notCls(test) {
  return { t: 'cls', test: ch => !test(ch) };
}

/** Any character; excludes newline unless `dotall`. */
export function any(dotall = false) {
  return { t: 'any', dotall };
}

export function seq(...items) {
  return { t: 'seq', items: items.flat() };
}

export function alt(...items) {
  return { t: 'alt', items: items.flat() };
}

/** Greedy repetition. `max` of `Infinity` means unbounded. */
export function rep(item, min = 0, max = Infinity) {
  return { t: 'rep', item, min, max, greedy: true };
}

/** Lazy repetition — stops as early as the continuation allows. */
export function lazy(item, min = 0, max = Infinity) {
  return { t: 'rep', item, min, max, greedy: false };
}

export function opt(item) {
  return rep(item, 0, 1);
}

export function lazyOpt(item) {
  return lazy(item, 0, 1);
}

/** Capturing group, numbered from 1. */
export function group(n, item) {
  return { t: 'group', n, item };
}

/** Backreference to a previously captured group. */
export function ref(n) {
  return { t: 'ref', n };
}

/** Lookahead. `neg` inverts it. */
export function ahead(item, neg = false) {
  return { t: 'ahead', item, neg };
}

/**
 * Fixed-width lookbehind expressed as a predicate on the preceding character.
 * `neg` inverts it; at the start of the subject there is no character, which
 * satisfies a negative lookbehind and fails a positive one.
 */
export function behind(test, neg = false) {
  return { t: 'behind', test, neg };
}

/** Lookbehind over a fixed-length literal. */
export function behindLit(s, neg = false) {
  return { t: 'behindLit', s, neg };
}

export const bos = { t: 'bos' };
export const eos = { t: 'eos' };
/** Start of a line (start of subject, or just after a newline). */
export const bol = { t: 'bol' };
/** End of a line (end of subject, or positioned on a newline). */
export const eol = { t: 'eol' };

// --- helpers ---------------------------------------------------------------

/** True when a repetition body consumes exactly one character. */
function isSingleChar(node) {
  return node.t === 'cls' || node.t === 'any' || (node.t === 'lit' && node.s.length === 1);
}

function charMatches(node, s, i) {
  if (i >= s.length) return false;
  if (node.t === 'cls') return node.test(s[i]);
  if (node.t === 'any') return node.dotall || s[i] !== '\n';
  return s[i] === node.s;
}

// --- evaluation ------------------------------------------------------------

function exec(node, s, i, st, k) {
  switch (node.t) {
    case 'lit': {
      if (s.startsWith(node.s, i)) return k(i + node.s.length);
      return FAIL;
    }
    case 'cls':
    case 'any': {
      if (charMatches(node, s, i)) return k(i + 1);
      return FAIL;
    }
    case 'seq': {
      const items = node.items;
      const step = (idx, pos) => (idx === items.length ? k(pos) : exec(items[idx], s, pos, st, p => step(idx + 1, p)));
      return step(0, i);
    }
    case 'alt': {
      for (const item of node.items) {
        const r = exec(item, s, i, st, k);
        if (r !== FAIL) return r;
      }
      return FAIL;
    }
    case 'rep':
      return execRep(node, s, i, st, k);
    case 'group': {
      const prev = st.groups[node.n];
      const r = exec(node.item, s, i, st, j => {
        const saved = st.groups[node.n];
        st.groups[node.n] = [i, j];
        const rr = k(j);
        if (rr === FAIL) st.groups[node.n] = saved;
        return rr;
      });
      if (r === FAIL) st.groups[node.n] = prev;
      return r;
    }
    case 'ref': {
      const g = st.groups[node.n];
      if (!g) return FAIL;                       // unset group never matches
      const text = s.slice(g[0], g[1]);
      if (s.startsWith(text, i)) return k(i + text.length);
      return FAIL;
    }
    case 'ahead': {
      const snapshot = st.groups.slice();
      const hit = exec(node.item, s, i, st, j => j);
      if (node.neg) {
        st.groups = snapshot;                    // negative lookahead keeps nothing
        return hit === FAIL ? k(i) : FAIL;
      }
      if (hit === FAIL) { st.groups = snapshot; return FAIL; }
      const r = k(i);
      if (r === FAIL) st.groups = snapshot;
      return r;
    }
    case 'behind': {
      const ch = i > 0 ? s[i - 1] : undefined;
      const hit = ch !== undefined && node.test(ch);
      return (node.neg ? !hit : hit) ? k(i) : FAIL;
    }
    case 'behindLit': {
      const start = i - node.s.length;
      const hit = start >= 0 && s.startsWith(node.s, start);
      return (node.neg ? !hit : hit) ? k(i) : FAIL;
    }
    case 'bos':
      return i === 0 ? k(i) : FAIL;
    case 'eos':
      return i === s.length ? k(i) : FAIL;
    case 'bol':
      return (i === 0 || s[i - 1] === '\n') ? k(i) : FAIL;
    case 'eol':
      return (i === s.length || s[i] === '\n') ? k(i) : FAIL;
    default:
      throw new Error('unknown matcher node: ' + node.t);
  }
}

function execRep(node, s, i, st, k) {
  const { item, min, max, greedy } = node;

  // Single-character bodies are the common case and can be counted directly,
  // which keeps deep repetitions from growing the call stack.
  if (isSingleChar(item)) {
    let n = 0;
    while (n < max && charMatches(item, s, i + n)) n++;
    if (n < min) return FAIL;
    if (greedy) {
      for (let c = n; c >= min; c--) {
        const r = k(i + c);
        if (r !== FAIL) return r;
      }
    } else {
      for (let c = min; c <= n; c++) {
        const r = k(i + c);
        if (r !== FAIL) return r;
      }
    }
    return FAIL;
  }

  const walk = (pos, count) => {
    if (greedy) {
      if (count < max) {
        const r = exec(item, s, pos, st, j => (j === pos ? FAIL : walk(j, count + 1)));
        if (r !== FAIL) return r;
      }
      return count >= min ? k(pos) : FAIL;
    }
    if (count >= min) {
      const r = k(pos);
      if (r !== FAIL) return r;
    }
    if (count < max) {
      return exec(item, s, pos, st, j => (j === pos ? FAIL : walk(j, count + 1)));
    }
    return FAIL;
  };
  return walk(i, 0);
}

// --- public surface --------------------------------------------------------

/**
 * A compiled grammar fragment. `groupCount` is the highest group number used,
 * so results can expose a stable, 1-indexed group array.
 */
export class Matcher {
  constructor(node, groupCount = 0) {
    this.node = node;
    this.groupCount = groupCount;
  }

  /** Anchored attempt at exactly `pos`. */
  matchAt(s, pos) {
    const st = { groups: new Array(this.groupCount + 1).fill(undefined) };
    const end = exec(this.node, s, pos, st, j => j);
    if (end === FAIL) return null;
    return makeResult(s, pos, end, st, this.groupCount);
  }

  /** First match at or after `from`, scanning forward one position at a time. */
  search(s, from = 0) {
    for (let pos = from; pos <= s.length; pos++) {
      const r = this.matchAt(s, pos);
      if (r) return r;
    }
    return null;
  }
}

function makeResult(s, start, end, st, groupCount) {
  const groups = [s.slice(start, end)];
  const spans = [[start, end]];
  for (let n = 1; n <= groupCount; n++) {
    const g = st.groups[n];
    groups.push(g ? s.slice(g[0], g[1]) : null);
    spans.push(g ? [g[0], g[1]] : null);
  }
  return {
    start,
    end,
    /** `group(0)` is the whole match; 1..n are the captures. */
    group(n = 0) { return groups[n]; },
    spanOf(n) { return spans[n]; },
    groups,
  };
}

