// Matcher trees for the inline grammar.
//
// One exported matcher per inline construct, built from the combinators in
// matcher.mjs. Newline is an ordinary character throughout (the reference
// patterns are all compiled in dot-matches-all mode), so inline constructs may
// span the lines of a single block.

import {
  Matcher, lit, cls, notCls, any, seq, alt, rep, lazy, opt, group, ref, ahead,
  behind, behindLit, bol, eol, bos, eos,
} from './matcher.mjs';
import { isWordChar, isRegexSpace, isDigit, isHexDigit, isAsciiAlpha, isAsciiAlnum } from './chars.mjs';

const dot = () => any(true);
const isChar = c => ch => ch === c;

// --- code spans ------------------------------------------------------------
// Either an even run of backslashes shielding the backticks that follow, or a
// run of backticks closed by an equal-length run.

export const BACKTICK = new Matcher(
  alt(
    seq(
      behindLit('\\', true),
      group(1, rep(lit('\\\\'), 1)),
      ahead(rep(lit('`'), 1)),
    ),
    seq(
      behindLit('\\', true),
      group(2, rep(lit('`'), 1)),
      group(3, lazy(dot(), 1)),
      behind(isChar('`'), true),
      ref(2),
      ahead(lit('`'), true),
    ),
  ),
  3,
);

// --- backslash escapes -----------------------------------------------------

export const ESCAPE = new Matcher(seq(lit('\\'), group(1, dot())), 1);

// --- links, images, references ---------------------------------------------
// These only locate the opening bracket; the bodies are scanned by hand so
// nested brackets and parentheses can be balanced.

export const LINK = new Matcher(seq(behind(isChar('!'), true), lit('[')), 0);
export const IMAGE_LINK = new Matcher(seq(lit('!'), lit('[')), 0);
export const REFERENCE = LINK;
export const IMAGE_REFERENCE = IMAGE_LINK;

/** `<url>` form of a link destination, with an optional title. */
export const LINK_ANGLE = new Matcher(
  seq(
    lit('('),
    rep(cls(isRegexSpace)),
    opt(seq(
      group(1, seq(lit('<'), rep(notCls(ch => ch === '<' || ch === '>')), lit('>'))),
      rep(cls(isRegexSpace)),
      opt(seq(
        group(2, cls(ch => ch === '"' || ch === "'")),
        group(3, lazy(dot())),
        ref(2),
        rep(cls(isRegexSpace)),
      )),
      lit(')'),
    )),
  ),
  3,
);

/** `[id]` following a link's text, optionally separated by one space. */
export const REFERENCE_ID = new Matcher(
  seq(
    opt(cls(isRegexSpace)),
    lit('['),
    group(1, rep(notCls(isChar(']')))),
    lit(']'),
  ),
  1,
);

// --- autolinks -------------------------------------------------------------

const httpScheme = seq(
  alt(
    cls(ch => ch === 'f' || ch === 'F'),
    seq(cls(ch => ch === 'h' || ch === 'H'), cls(ch => ch === 't' || ch === 'T')),
  ),
  cls(ch => ch === 't' || ch === 'T'),
  cls(ch => ch === 'p' || ch === 'P'),
  opt(cls(ch => ch === 's' || ch === 'S')),
  lit('://'),
);

export const AUTOLINK = new Matcher(
  seq(
    lit('<'),
    group(1, seq(httpScheme, rep(notCls(ch => ch === '<' || ch === '>')))),
    lit('>'),
  ),
  1,
);

export const AUTOMAIL = new Matcher(
  seq(
    lit('<'),
    group(1, seq(
      rep(notCls(ch => ch === '<' || ch === '>' || ch === ' ' || ch === '!'), 1),
      lit('@'),
      rep(notCls(ch => ch === '@' || ch === '<' || ch === '>' || ch === ' '), 1),
    )),
    lit('>'),
  ),
  1,
);

// --- hard line break -------------------------------------------------------

export const LINE_BREAK = new Matcher(lit('  \n'), 0);

// --- inline raw html and character references ------------------------------
// A tag-like run with no `@` in it, or a comment.

export const HTML = new Matcher(
  group(1, seq(
    lit('<'),
    group(2, alt(
      seq(
        opt(lit('/')),
        cls(isAsciiAlpha),
        lazy(notCls(ch => ch === '<' || ch === '>' || ch === '@')),
      ),
      seq(
        lit('!--'),
        lazy(seq(ahead(alt(lit('<!--'), lit('-->')), true), dot())),
        lit('--'),
      ),
    )),
    lit('>'),
  )),
  2,
);

export const ENTITY = new Matcher(
  group(1, seq(
    lit('&'),
    alt(
      seq(lit('#'), rep(cls(isDigit), 1)),
      seq(lit('#x'), rep(cls(isHexDigit), 1)),
      rep(cls(isAsciiAlnum), 1),
    ),
    lit(';'),
  )),
  1,
);

// --- a lone emphasis character is literal ----------------------------------

export const NOT_STRONG = new Matcher(
  group(1, seq(
    group(2, alt(bos, cls(isRegexSpace))),
    group(3, cls(ch => ch === '*' || ch === '_')),
    group(4, alt(cls(isRegexSpace), eos)),
  )),
  4,
);

// --- emphasis and strong ---------------------------------------------------
// Tried in the order listed; the first that matches at the position wins, and
// its `builder` decides how the captures nest.

const star = () => group(1, lit('*'));
const under = () => group(1, lit('_'));
const notWordBehind = () => behind(isWordChar, true);
const notWordAhead = () => ahead(cls(isWordChar), true);

/** `***em*strong**` / `***both***` */
const EM_STRONG = new Matcher(
  seq(star(), rep(ref(1), 2, 2), group(2, lazy(dot(), 1)), ref(1), group(3, lazy(dot())), rep(ref(1), 2, 2)),
  3,
);

/** `***strong**em*` */
const STRONG_EM = new Matcher(
  seq(star(), rep(ref(1), 2, 2), group(2, lazy(dot(), 1)), rep(ref(1), 2, 2), group(3, lazy(dot())), ref(1)),
  3,
);

/** `**strong*em***` */
const STRONG_EM3 = new Matcher(
  seq(
    star(), ref(1), ahead(ref(1), true),
    group(2, lazy(notCls(isChar('*')), 1)),
    ref(1), ahead(ref(1), true),
    group(3, lazy(dot(), 1)),
    rep(ref(1), 3, 3),
  ),
  3,
);

/** `**strong**` */
const STRONG = new Matcher(
  seq(group(1, lit('**')), group(2, lazy(dot(), 1)), ref(1)),
  2,
);

/** `*em*` */
const EMPHASIS = new Matcher(
  seq(group(1, lit('*')), group(2, rep(notCls(isChar('*')), 1)), ref(1)),
  2,
);

/** `___em_strong__` */
const EM_STRONG2 = new Matcher(
  seq(under(), rep(ref(1), 2, 2), group(2, lazy(dot(), 1)), ref(1), group(3, lazy(dot())), rep(ref(1), 2, 2)),
  3,
);

/** `___strong__em_` */
const STRONG_EM2 = new Matcher(
  seq(under(), rep(ref(1), 2, 2), group(2, lazy(dot(), 1)), rep(ref(1), 2, 2), group(3, lazy(dot())), ref(1)),
  3,
);

/** `__strong _em___` */
const SMART_STRONG_EM = new Matcher(
  seq(
    notWordBehind(), under(), ref(1), ahead(ref(1), true),
    group(2, lazy(dot(), 1)),
    notWordBehind(), ref(1), ahead(ref(1), true),
    group(3, lazy(dot(), 1)),
    rep(ref(1), 3, 3),
    notWordAhead(),
  ),
  3,
);

/** `__strong__`, but not inside a word. */
const SMART_STRONG = new Matcher(
  seq(
    notWordBehind(), group(1, lit('__')), ahead(lit('_'), true),
    group(2, lazy(dot(), 1)),
    behind(isChar('_'), true), ref(1), notWordAhead(),
  ),
  2,
);

/** `_em_`, but not inside a word. */
const SMART_EMPHASIS = new Matcher(
  seq(
    notWordBehind(), group(1, lit('_')), ahead(lit('_'), true),
    group(2, lazy(dot(), 1)),
    behind(isChar('_'), true), ref(1), notWordAhead(),
  ),
  2,
);

/** Ordered list of emphasis shapes delimited by asterisks. */
export const ASTERISK_PATTERNS = [
  { matcher: EM_STRONG, builder: 'double', tags: 'strong,em' },
  { matcher: STRONG_EM, builder: 'double', tags: 'em,strong' },
  { matcher: STRONG_EM3, builder: 'double2', tags: 'strong,em' },
  { matcher: STRONG, builder: 'single', tags: 'strong' },
  { matcher: EMPHASIS, builder: 'single', tags: 'em' },
];

/** Ordered list of emphasis shapes delimited by underscores. */
export const UNDERSCORE_PATTERNS = [
  { matcher: EM_STRONG2, builder: 'double', tags: 'strong,em' },
  { matcher: STRONG_EM2, builder: 'double', tags: 'em,strong' },
  { matcher: SMART_STRONG_EM, builder: 'double2', tags: 'strong,em' },
  { matcher: SMART_STRONG, builder: 'single', tags: 'strong' },
  { matcher: SMART_EMPHASIS, builder: 'single', tags: 'em' },
];

/** Cheap gate: only positions holding the delimiter are worth trying. */
export const ASTERISK_TRIGGER = new Matcher(lit('*'), 0);
export const UNDERSCORE_TRIGGER = new Matcher(lit('_'), 0);

