      seq(lit('#x'), rep(cls(isHexDigit), 1)),
      rep(cls(isAsciiAlnum), 1),
    ),
    lit(';'),
  )),
  1,
);

// --- a lone emphasis character is literal ----------------------------------

export const NOT_STRONG = new Matcher(
  group(1, seq(
    group(2, alt(bos, cls(isRegexSpace))),
    group(3, cls(ch => ch === '*' || ch === '_')),
    group(4, alt(cls(isRegexSpace), eos)),
  )),
  4,
);

// --- emphasis and strong ---------------------------------------------------
// Tried in the order listed; the first that matches at the position wins, and
// its `builder` decides how the captures nest.

const star = () => group(1, lit('*'));
const under = () => group(1, lit('_'));
const notWordBehind = () => behind(isWordChar, true);
const notWordAhead = () => ahead(cls(isWordChar), true);

/** `***em*strong**` / `***both***` */
const EM_STRONG = new Matcher(
  seq(star(), rep(ref(1), 2, 2), group(2, lazy(dot(), 1)), ref(1), group(3, lazy(dot())), rep(ref(1), 2, 2)),
  3,
);

/** `***strong**em*` */
const STRONG_EM = new Matcher(
  seq(star(), rep(ref(1), 2, 2), group(2, lazy(dot(), 1)), rep(ref(1), 2, 2), group(3, lazy(dot())), ref(1)),
  3,
);

/** `**strong*em***` */
const STRONG_EM3 = new Matcher(
  seq(
    star(), ref(1), ahead(ref(1), true),
    group(2, lazy(notCls(isChar('*')), 1)),
    ref(1), ahead(ref(1), true),
    group(3, lazy(dot(), 1)),
    rep(ref(1), 3, 3),
  ),
  3,
);

/** `**strong**` */
const STRONG = new Matcher(
  seq(group(1, lit('**')), group(2, lazy(dot(), 1)), ref(1)),
  2,
);

/** `*em*` */
const EMPHASIS = new Matcher(
  seq(group(1, lit('*')), group(2, rep(notCls(isChar('*')), 1)), ref(1)),
  2,
);

/** `___em_strong__` */
const EM_STRONG2 = new Matcher(
  seq(under(), rep(ref(1), 2, 2), group(2, lazy(dot(), 1)), ref(1), group(3, lazy(dot())), rep(ref(1), 2, 2)),
  3,
);

/** `___strong__em_` */
const STRONG_EM2 = new Matcher(
  seq(under(), rep(ref(1), 2, 2), group(2, lazy(dot(), 1)), rep(ref(1), 2, 2), group(3, lazy(dot())), ref(1)),
  3,
);

/** `__strong _em___` */
const SMART_STRONG_EM = new Matcher(
  seq(
    notWordBehind(), under(), ref(1), ahead(ref(1), true),
    group(2, lazy(dot(), 1)),
    notWordBehind(), ref(1), ahead(ref(1), true),
    group(3, lazy(dot(), 1)),
    rep(ref(1), 3, 3),
    notWordAhead(),
  ),
  3,
);

/** `__strong__`, but not inside a word. */
const SMART_STRONG = new Matcher(
  seq(
    notWordBehind(), group(1, lit('__')), ahead(lit('_'), true),
    group(2, lazy(dot(), 1)),
    behind(isChar('_'), true), ref(1), notWordAhead(),
  ),
  2,
);

/** `_em_`, but not inside a word. */
const SMART_EMPHASIS = new Matcher(
  seq(
    notWordBehind(), group(1, lit('_')), ahead(lit('_'), true),
    group(2, lazy(dot(), 1)),
    behind(isChar('_'), true), ref(1), notWordAhead(),
  ),
  2,
);

/** Ordered list of emphasis shapes delimited by asterisks. */
export const ASTERISK_PATTERNS = [
  { matcher: EM_STRONG, builder: 'double', tags: 'strong,em' },
  { matcher: STRONG_EM, builder: 'double', tags: 'em,strong' },
  { matcher: STRONG_EM3, builder: 'double2', tags: 'strong,em' },
  { matcher: STRONG, builder: 'single', tags: 'strong' },
  { matcher: EMPHASIS, builder: 'single', tags: 'em' },
];

/** Ordered list of emphasis shapes delimited by underscores. */
export const UNDERSCORE_PATTERNS = [
  { matcher: EM_STRONG2, builder: 'double', tags: 'strong,em' },
  { matcher: STRONG_EM2, builder: 'double', tags: 'em,strong' },
  { matcher: SMART_STRONG_EM, builder: 'double2', tags: 'strong,em' },
  { matcher: SMART_STRONG, builder: 'single', tags: 'strong' },
  { matcher: SMART_EMPHASIS, builder: 'single', tags: 'em' },
];

/** Cheap gate: only positions holding the delimiter are worth trying. */
export const ASTERISK_TRIGGER = new Matcher(lit('*'), 0);
export const UNDERSCORE_TRIGGER = new Matcher(lit('_'), 0);

