// Inline processors.
//
// Each processor pairs a matcher with a `handleMatch` that turns a match into
// either an element, a literal string, or a rejection. Returning
// `[null, null, null]` means "not actually a match here, keep scanning"; a
// returned element is stashed behind a placeholder so that lower-priority
// processors cannot see inside it.

import { Element } from './element.mjs';
import { codeEscape } from './serializer.mjs';
import { STX, ETX, AMP_SUBSTITUTE } from './constants.mjs';
import { pyStrip, isRegexSpace, replaceAll } from './chars.mjs';
import { codepointToName } from './entities.mjs';
import {
  BACKTICK, ESCAPE, LINK, IMAGE_LINK, REFERENCE, IMAGE_REFERENCE,
  LINK_ANGLE, REFERENCE_ID, AUTOLINK, AUTOMAIL, LINE_BREAK, HTML, ENTITY,
  NOT_STRONG, ASTERISK_PATTERNS, UNDERSCORE_PATTERNS,
  ASTERISK_TRIGGER, UNDERSCORE_TRIGGER,
} from './inline-grammar.mjs';

/** Characters a backslash may escape; anything else keeps its backslash. */
export const ESCAPED_CHARS = ['\\', '`', '*', '_', '{', '}', '[', ']', '(', ')',
  '>', '#', '+', '-', '.', '!'];

/** Wrap a character as the sentinel form the unescape pass restores. */
export function stashChar(ch) {
  return STX + ch.codePointAt(0) + ETX;
}

class InlineProcessor {
  constructor(matcher, md = null) {
    this.matcher = matcher;
    this.md = md;
    this.ancestorExcludes = [];
  }

  /** Resolve inline placeholders back to serialized markup. */
  unescape(text) {
    const tp = this.md && this.md.treeprocessors.has('inline')
      ? this.md.treeprocessors.get('inline') : null;
    if (!tp) return text;
    return tp.restorePlaceholders(text);
  }

  /** Turn sentinel-wrapped characters back into the characters themselves. */
  backslashUnescape(text) {
    return unescapeSentinels(text);
  }
}

/** Replace every `STX<codepoint>ETX` run with the character it stands for. */
export function unescapeSentinels(text) {
  let out = '';
  let i = 0;
  while (i < text.length) {
    if (text[i] === STX) {
      let j = i + 1;
      let digits = '';
      while (j < text.length && text[j] >= '0' && text[j] <= '9') { digits += text[j]; j++; }
      if (digits && text[j] === ETX) {
        out += String.fromCodePoint(Number(digits));
        i = j + 1;
        continue;
      }
    }
    out += text[i];
    i++;
  }
  return out;
}

// ---------------------------------------------------------------------------

export class BacktickInlineProcessor extends InlineProcessor {
  constructor(matcher, md) {
    super(matcher, md);
    this.ESCAPED_BSLASH = STX + '92' + ETX;
    this.tag = 'code';
  }

  handleMatch(m, data) {
    if (m.group(3)) {
      const el = new Element(this.tag);
      el.setAtomicText(codeEscape(pyStrip(m.group(3))));
      return [el, m.start, m.end];
    }
    // An even run of backslashes: emit it literally, with the pairs collapsed
    // to sentinels so the unescape pass yields single backslashes.
    return [replaceAll(m.group(1), '\\\\', this.ESCAPED_BSLASH), m.start, m.end];
  }
}

export class EscapeInlineProcessor extends InlineProcessor {
  handleMatch(m, data) {
    const ch = m.group(1);
    if (ESCAPED_CHARS.includes(ch)) return [stashChar(ch), m.start, m.end];
    return [null, m.start, m.end];
  }
}

/** Emits a bare element, e.g. the `<br />` for a hard line break. */
export class SubstituteTagInlineProcessor extends InlineProcessor {
  constructor(matcher, tag) {
    super(matcher, null);
    this.tag = tag;
  }

  handleMatch(m, data) {
    return [new Element(this.tag), m.start, m.end];
  }
}

/** Emits `group(1)` verbatim — used to keep a lone `*` or `_` literal. */
export class SimpleTextInlineProcessor extends InlineProcessor {
  handleMatch(m, data) {
    return [m.group(1), m.start, m.end];
  }
}

/** Stashes raw inline HTML and character references so they pass through. */
export class HtmlInlineProcessor extends InlineProcessor {
  handleMatch(m, data) {
    const rawhtml = this.backslashUnescape(this.unescape(m.group(1)));
    return [this.md.htmlStash.store(rawhtml), m.start, m.end];
  }
}

export class AutolinkInlineProcessor extends InlineProcessor {
  handleMatch(m, data) {
    const el = new Element('a');
    el.set('href', this.unescape(m.group(1)));
    el.setAtomicText(m.group(1));
    return [el, m.start, m.end];
  }
}

/** Obfuscates a bare email address into character references. */
export class AutomailInlineProcessor extends InlineProcessor {
  handleMatch(m, data) {
    const el = new Element('a');
    let email = this.unescape(m.group(1));
    if (email.startsWith('mailto:')) email = email.slice('mailto:'.length);

    const encode = cp => {
      const name = codepointToName(cp);
      return name ? AMP_SUBSTITUTE + name + ';' : AMP_SUBSTITUTE + '#' + cp + ';';
    };

    let text = '';
    for (const ch of email) text += encode(ch.codePointAt(0));
    el.setAtomicText(text);

    let href = '';
    for (const ch of 'mailto:' + email) href += AMP_SUBSTITUTE + '#' + ch.codePointAt(0) + ';';
    el.set('href', href);
    return [el, m.start, m.end];
  }
}

// ---------------------------------------------------------------------------
// Links and images.
// ---------------------------------------------------------------------------

export class LinkInlineProcessor extends InlineProcessor {
  handleMatch(m, data) {
    const t = this.getText(data, m.end);
    if (!t.handled) return [null, null, null];
    const l = this.getLink(data, t.index);
    if (!l.handled) return [null, null, null];

    const el = new Element('a');
    el.text = t.text;
    el.set('href', l.href);
    if (l.title !== null) el.set('title', l.title);
    return [el, m.start, l.index];
  }

  /** Content between `[` and its balancing `]`, allowing nested brackets. */
  getText(data, index) {
    let bracketCount = 1;
    let text = '';
    let pos = index;
    for (; pos < data.length; pos++) {
      const c = data[pos];
      if (c === ']') bracketCount -= 1;
      else if (c === '[') bracketCount += 1;
      index = pos + 1;
      if (bracketCount === 0) break;
      text += c;
    }
    return { text, index, handled: bracketCount === 0 };
  }

  /**
   * Destination and title between `(` and its balancing `)`.
   *
   * A quoted run at the end of the destination is the title: it starts at the
   * first quote character and runs to the last quote of the same kind, so
   * `(u "a" "b")` yields the title `a" "b` rather than two titles.
   */
  getLink(data, index) {
    if (data[index] !== '(') return { href: '', title: null, index, handled: false };

    const angle = LINK_ANGLE.matchAt(data, index);
    if (angle && angle.group(1)) {
      const href = pyStrip(angle.group(1).slice(1, -1));
      const title = angle.group(3) ? angle.group(3) : null;
      return { href, title, index: angle.end, handled: true };
    }

    // Walk to the balancing parenthesis.
    let depth = 1;
    let pos = index + 1;
    let close = -1;
    for (; pos < data.length; pos++) {
      const c = data[pos];
      if (c === '(') depth += 1;
      else if (c === ')') {
        depth -= 1;
        if (depth === 0) { close = pos; break; }
      }
    }
    if (close === -1) return { href: '', title: null, index, handled: false };

    const inner = data.slice(index + 1, close);
    let href = inner;
    let title = null;

    const q = firstQuote(inner);
    if (q !== -1) {
      const last = inner.lastIndexOf(inner[q]);
      if (last > q) {
        const after = inner.slice(last + 1);
        if (pyStrip(after) === '') {
          href = inner.slice(0, q);
          title = inner.slice(q + 1, last);
        }
      }
    }

    return { href: pyStrip(href), title, index: close + 1, handled: true };
  }
}

function firstQuote(text) {
  for (let i = 0; i < text.length; i++) {
    if (text[i] === '"' || text[i] === "'") return i;
  }
  return -1;
}

export class ImageInlineProcessor extends LinkInlineProcessor {
  handleMatch(m, data) {
    const t = this.getText(data, m.end);
    if (!t.handled) return [null, null, null];
    const l = this.getLink(data, t.index);
    if (!l.handled) return [null, null, null];

    const el = new Element('img');
    el.set('src', l.href);
    if (l.title !== null) el.set('title', l.title);
    el.set('alt', this.unescape(t.text));
    return [el, m.start, l.index];
  }
}

export class ReferenceInlineProcessor extends LinkInlineProcessor {
  handleMatch(m, data) {
    const t = this.getText(data, m.end);
    if (!t.handled) return [null, null, null];
    const e = this.evalId(data, t.index, t.text);
    if (!e.handled) return [null, null, null];

    const id = collapseWhitespace(e.id);
    if (!this.md.references.has(id)) return [null, m.start, e.end];

    const [href, title] = this.md.references.get(id);
    return [this.makeTag(href, title, t.text), m.start, e.end];
  }

  /** `[text][id]`, or `[text][]` which reuses the text as the id. */
  evalId(data, index, text) {
    const m = REFERENCE_ID.matchAt(data, index);
    if (!m) return { id: null, end: index, handled: false };
    let id = m.group(1).toLowerCase();
    if (!id) id = text.toLowerCase();
    return { id, end: m.end, handled: true };
  }

  makeTag(href, title, text) {
    const el = new Element('a');
    el.set('href', href);
    if (title) el.set('title', title);
    el.text = text;
    return el;
  }
}

/** `[id]` on its own, resolved against the definitions. */
export class ShortReferenceInlineProcessor extends ReferenceInlineProcessor {
  evalId(data, index, text) {
    return { id: text.toLowerCase(), end: index, handled: true };
  }
}

export class ImageReferenceInlineProcessor extends ReferenceInlineProcessor {
  makeTag(href, title, text) {
    const el = new Element('img');
    el.set('src', href);
    if (title) el.set('title', title);
    el.set('alt', this.unescape(text));
    return el;
  }
}

export class ShortImageReferenceInlineProcessor extends ImageReferenceInlineProcessor {
  evalId(data, index, text) {
    return { id: text.toLowerCase(), end: index, handled: true };
  }
}

function collapseWhitespace(text) {
  let out = '';
  let inRun = false;
  for (const ch of text) {
    if (isRegexSpace(ch)) {
      if (!inRun) { out += ' '; inRun = true; }
    } else {
      out += ch;
      inRun = false;
    }
  }
  return out;
}

// ---------------------------------------------------------------------------
// Emphasis and strong.
//
// Both delimiters share this machinery; only the ordered pattern list differs.
// `parseSubPatterns` re-scans the captured content for further emphasis, but
// only with patterns *after* the one that produced the parent, which is what
// stops `**a**` from being re-read as `*` + `*a*` + `*`.
// ---------------------------------------------------------------------------

export class EmStrongProcessor extends InlineProcessor {
  constructor(trigger, patterns, md) {
    super(trigger, md);
    this.patterns = patterns;
  }

  handleMatch(m, data) {
    for (let index = 0; index < this.patterns.length; index++) {
      const item = this.patterns[index];
      const m1 = item.matcher.matchAt(data, m.start);
      if (m1) {
        return [this.buildElement(m1, item.builder, item.tags, index), m1.start, m1.end];
      }
    }
    return [null, null, null];
  }

  buildElement(m, builder, tags, index) {
    if (builder === 'double2') return this.buildDouble2(m, tags, index);
    if (builder === 'double') return this.buildDouble(m, tags, index);
    return this.buildSingle(m, tags, index);
  }

  buildSingle(m, tag, idx) {
    const el = new Element(tag);
    this.parseSubPatterns(m.group(2), el, null, idx);
    return el;
  }

  /** `<outer>…<inner>…</inner>tail</outer>` */
  buildDouble(m, tags, idx) {
    const [tag1, tag2] = tags.split(',');
    const el1 = new Element(tag1);
    const el2 = new Element(tag2);
    this.parseSubPatterns(m.group(2), el2, null, idx);
    el1.append(el2);
    this.parseSubPatterns(m.group(3), el1, el2, idx);
    return el1;
  }

  /** `<outer>text<inner>text</inner></outer>` */
  buildDouble2(m, tags, idx) {
    const [tag1, tag2] = tags.split(',');
    const el1 = new Element(tag1);
    const el2 = new Element(tag2);
    this.parseSubPatterns(m.group(2), el1, null, idx);
    this.parseSubPatterns(m.group(3), el2, null, idx);
    el1.append(el2);
    return el1;
  }

  parseSubPatterns(data, parent, last, idx) {
    let offset = 0;
    let pos = 0;
    const length = data.length;

    while (pos < length) {
      if (this.matcher.matchAt(data, pos)) {
        let matched = false;
        for (let index = 0; index < this.patterns.length; index++) {
          if (index <= idx) continue;   // only shapes weaker than the parent's
          const m = this.patterns[index].matcher.matchAt(data, pos);
          if (m) {
            const text = data.slice(offset, m.start);
            if (text) {
              if (last !== null) last.tail = text;
              else parent.text = text;
            }
            const el = this.buildElement(m, this.patterns[index].builder, this.patterns[index].tags, index);
            parent.append(el);
            last = el;
            offset = m.end;
            pos = m.end;
            matched = true;
          }
        }
        if (!matched) pos += 1;
      } else {
        pos += 1;
      }
    }

    const text = data.slice(offset);
    if (text) {
      if (last !== null) last.tail = text;
      else parent.text = text;
    }
  }
}

// ---------------------------------------------------------------------------

export function buildInlinePatterns(md, Registry) {
  const reg = new Registry();
  reg.register(new BacktickInlineProcessor(BACKTICK, md), 'backtick', 190);
  reg.register(new EscapeInlineProcessor(ESCAPE, md), 'escape', 180);
  reg.register(new ReferenceInlineProcessor(REFERENCE, md), 'reference', 170);
  reg.register(new LinkInlineProcessor(LINK, md), 'link', 160);
  reg.register(new ImageInlineProcessor(IMAGE_LINK, md), 'image_link', 150);
  reg.register(new ImageReferenceInlineProcessor(IMAGE_REFERENCE, md), 'image_reference', 140);
  reg.register(new ShortReferenceInlineProcessor(REFERENCE, md), 'short_reference', 130);
  reg.register(new ShortImageReferenceInlineProcessor(IMAGE_REFERENCE, md), 'short_image_ref', 125);
  reg.register(new AutolinkInlineProcessor(AUTOLINK, md), 'autolink', 120);
  reg.register(new AutomailInlineProcessor(AUTOMAIL, md), 'automail', 110);
  reg.register(new SubstituteTagInlineProcessor(LINE_BREAK, 'br'), 'linebreak', 100);
  reg.register(new HtmlInlineProcessor(HTML, md), 'html', 90);
  reg.register(new HtmlInlineProcessor(ENTITY, md), 'entity', 80);
  reg.register(new SimpleTextInlineProcessor(NOT_STRONG, md), 'not_strong', 70);
  reg.register(new EmStrongProcessor(ASTERISK_TRIGGER, ASTERISK_PATTERNS, md), 'em_strong', 60);
  reg.register(new EmStrongProcessor(UNDERSCORE_TRIGGER, UNDERSCORE_PATTERNS, md), 'em_strong2', 50);
  return reg;
}

