import { Element } from './element.mjs';
import { STX, ETX, INLINE_PLACEHOLDER_PREFIX, inlinePlaceholder } from './constants.mjs';
import { isBlankString } from './chars.mjs';
import { toHtmlString } from './serializer.mjs';
import { unescapeSentinels } from './inlinepatterns.mjs';

/**
 * Applies the inline grammar.
