 * The indirection is what lets a lower-priority pattern scan the text without
 * seeing inside a construct a higher-priority pattern already claimed.
 */
export class InlineTreeProcessor {
  constructor(md) {
    this.md = md;
    this.stashedNodes = new Map();
    this.ancestors = [];
  }

  makePlaceholder() {
    const id = String(this.stashedNodes.size).padStart(4, '0');
    return [inlinePlaceholder(id), id];
  }

  stashNode(node) {
    const [placeholder, id] = this.makePlaceholder();
    this.stashedNodes.set(id, node);
    return placeholder;
  }

  /** Serialize any placeholders in `text` back to markup. */
  restorePlaceholders(text) {
    let out = '';
    let i = 0;
    while (i < text.length) {
      if (text.startsWith(INLINE_PLACEHOLDER_PREFIX, i)) {
        const idStart = i + INLINE_PLACEHOLDER_PREFIX.length;
        let j = idStart;
        while (j < text.length && text[j] >= '0' && text[j] <= '9') j++;
        if (j > idStart && text[j] === ETX) {
          const id = text.slice(idStart, j);
          const value = this.stashedNodes.get(id);
          if (value !== undefined) {
            out += typeof value === 'string' ? value : toHtmlString(value);
            i = j + 1;
            continue;
          }
        }
      }
      out += text[i];
      i++;
    }
    return out;
  }

  /** Find the next placeholder id at or after `index`. */
  findPlaceholder(data, index) {
    let i = data.indexOf(INLINE_PLACEHOLDER_PREFIX, index);
    while (i !== -1) {
      const idStart = i + INLINE_PLACEHOLDER_PREFIX.length;
      let j = idStart;
      while (j < data.length && data[j] >= '0' && data[j] <= '9') j++;
      if (j > idStart && data[j] === ETX) {
        return { id: data.slice(idStart, j), end: j + 1 };
      }
      i = data.indexOf(INLINE_PLACEHOLDER_PREFIX, i + 1);
    }
    return { id: null, end: index + 1 };
  }

  /**
   * Rewrite `data`, replacing every inline construct with a placeholder.
   * Patterns are applied in priority order; a pattern that matched is retried
   * from the start of the rewritten string before moving on to the next.
   */
  handleInline(data, patternIndex = 0) {
    let startIndex = 0;
    const patterns = this.md.inlinePatterns.ordered;
    while (patternIndex < patterns.length) {
      const r = this.applyPattern(patterns[patternIndex], data, patternIndex, startIndex);
      data = r.data;
      startIndex = r.startIndex;
      if (!r.matched) patternIndex += 1;
    }
    return data;
  }

  applyPattern(pattern, data, patternIndex, startIndex = 0) {
    for (const exclude of pattern.ancestorExcludes) {
      if (this.ancestors.includes(exclude.toLowerCase())) {
        return { data, matched: true, startIndex: data.length };
      }
    }

    // `handleMatch` may decline a match, so keep scanning until one sticks.
    let node = null;
    let start = null;
    let end = null;
    let found = false;
    let scanFrom = startIndex;
    for (;;) {
      const m = pattern.matcher.search(data, scanFrom);
      if (!m) break;
      const res = pattern.handleMatch(m, data);
      if (res[1] === null || res[2] === null) {
        startIndex += m.end;
        scanFrom = m.end > scanFrom ? m.end : scanFrom + 1;
        continue;
      }
      [node, start, end] = res;
      found = true;
      break;
    }

    if (!found) return { data, matched: false, startIndex: 0 };
    if (node === null) return { data, matched: true, startIndex: end };

    if (typeof node !== 'string' && !node.textAtomic) {
      // The construct's own content still needs weaker patterns applied.
      for (const child of [node, ...node.children]) {
        if (child.text) {
          this.ancestors.push(String(child.tag).toLowerCase());
          child.text = this.handleInline(child.text, patternIndex + 1);
          this.ancestors.pop();
        }
        if (child.tail) {
          child.tail = this.handleInline(child.tail, patternIndex);
        }
      }
    }

    const placeholder = this.stashNode(node);
    return {
      data: data.slice(0, start) + placeholder + data.slice(end),
      matched: true,
      startIndex: 0,
    };
  }

  /**
   * Expand placeholders in `data` into children of `parent`, returning the new
   * elements in document order. Text between placeholders lands on the previous
   * element's tail, or on the parent's text/tail when there is none yet.
   */
  processPlaceholders(data, parent, isText = true) {
    const result = [];

    const linkText = text => {
      if (!text) return;
      if (result.length) {
        const last = result[result.length - 1];
        last.tail = last.tail ? last.tail + text : text;
      } else if (!isText) {
        parent.tail = parent.tail ? parent.tail + text : text;
      } else {
        parent.text = parent.text ? parent.text + text : text;
      }
    };

    let startIndex = 0;
    while (data) {
      const index = data.indexOf(INLINE_PLACEHOLDER_PREFIX, startIndex);
      if (index !== -1) {
        const { id, end: phEnd } = this.findPlaceholder(data, index);
        if (id !== null && this.stashedNodes.has(id)) {
          const node = this.stashedNodes.get(id);
          if (index > startIndex) linkText(data.slice(startIndex, index));

          if (typeof node === 'string') {
            linkText(node);
            startIndex = phEnd;
            continue;
          }

          // Expand any placeholders nested in the construct itself.
          for (const child of [node, ...node.children]) {
            if (child.tail && !isBlankString(child.tail)) {
              this.processElementText(node, child, false);
            }
            if (child.text && !isBlankString(child.text)) {
              this.processElementText(child, child, true);
            }
          }

          startIndex = phEnd;
          result.push(node);
        } else {
          const end = index + INLINE_PLACEHOLDER_PREFIX.length;
          linkText(data.slice(startIndex, end));
          startIndex = end;
        }
      } else {
        linkText(data.slice(startIndex));
        data = '';
      }
    }
    return result;
  }

  processElementText(node, subnode, isText) {
    let text;
    if (isText) { text = subnode.text; subnode.text = null; }
    else { text = subnode.tail; subnode.tail = null; }

    const childResult = this.processPlaceholders(text, subnode, isText);
    const pos = (!isText && node !== subnode) ? node.indexOf(subnode) + 1 : 0;
    for (let i = childResult.length - 1; i >= 0; i--) node.insert(pos, childResult[i]);
  }

  buildAncestors(parent, parents) {
    if (parent !== null && parent.tag !== null) parents.push(String(parent.tag).toLowerCase());
  }

  run(tree, ancestors = null) {
    this.stashedNodes = new Map();
    const treeParents = ancestors === null ? [] : ancestors.slice();
    const stack = [[tree, treeParents]];

    while (stack.length) {
      const [currElement, parents] = stack.pop();
      this.ancestors = parents;
      this.buildAncestors(currElement, this.ancestors);

      const insertQueue = [];
      for (const child of currElement.children.slice()) {
        if (child.text && !child.textAtomic) {
          this.ancestors.push(String(child.tag).toLowerCase());
          const text = child.text;
          child.text = null;
          const lst = this.processPlaceholders(this.handleInline(text), child, true);
          insertQueue.push([child, lst]);
          this.ancestors.pop();
        }

        if (child.tail) {
          const tail = this.handleInline(child.tail);
          const dummy = new Element('d');
          child.tail = null;
          const tailResult = this.processPlaceholders(tail, dummy, false);
          if (dummy.tail) child.tail = dummy.tail;
          const pos = currElement.indexOf(child) + 1;
          for (let i = tailResult.length - 1; i >= 0; i--) currElement.insert(pos, tailResult[i]);
        }

        if (child.length) stack.push([child, this.ancestors.slice()]);
      }

      for (const [element, lst] of insertQueue) {
        let i = 0;
        for (const newChild of lst) { element.insert(i, newChild); i += 1; }
      }
    }
    return tree;
  }
}

/**
 * Adds the newlines that make the output readable: one after every block-level
 * element, one before the first block-level child, one after every `<br />`,
 * and a single trailing newline inside code blocks.
 */
export class PrettifyTreeProcessor {
  constructor(md) {
    this.md = md;
  }

  prettifyEtree(elem) {
    const i = '\n';
    if (this.md.isBlockLevel(elem.tag) && elem.tag !== 'code' && elem.tag !== 'pre') {
      if ((!elem.text || isBlankString(elem.text)) && elem.length
          && this.md.isBlockLevel(elem.at(0).tag)) {
        elem.text = i;
      }
      for (const e of elem.children) {
        if (this.md.isBlockLevel(e.tag)) this.prettifyEtree(e);
      }
      if (!elem.tail || isBlankString(elem.tail)) elem.tail = i;
    }
  }

  run(root) {
    this.prettifyEtree(root);
    // `<br />` usually sits mid-sentence, so it is handled separately.
    for (const e of root.iter('br')) {
      if (!e.tail || isBlankString(e.tail)) e.tail = '\n';
    }
    // Collapse the blank lines that accumulate at the end of a code block.
    for (const pre of root.iter('pre')) {
      if (pre.length && pre.at(0).tag === 'code') {
        const code = pre.at(0);
        if (!code.length && code.text !== null) {
          code.setAtomicText(rstripAll(code.text) + '\n');
        }
      }
    }
    return root;
  }
}

function rstripAll(text) {
  let end = text.length;
  while (end > 0) {
    const ch = text[end - 1];
    if (ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r' || ch === '\v' || ch === '\f') end--;
    else break;
  }
  return text.slice(0, end);
}

/** Restores characters that were shielded from the inline passes. */
export class UnescapeTreeProcessor {
  constructor(md) {
    this.md = md;
  }

  run(root) {
    for (const el of root.iter()) {
      if (typeof el.tag === 'string') {
        for (const [k, v] of [...el.attrib]) {
          if (typeof v === 'string') el.attrib.set(k, unescapeSentinels(v));
        }
      }
      if (el.text) el.text = unescapeSentinels(el.text);
      if (el.tail) el.tail = unescapeSentinels(el.tail);
    }
    return root;
  }
}

export function buildTreeProcessors(md, Registry) {
  const reg = new Registry();
  reg.register(new InlineTreeProcessor(md), 'inline', 20);
  reg.register(new PrettifyTreeProcessor(md), 'prettify', 10);
  reg.register(new UnescapeTreeProcessor(md), 'unescape', 0);
  return reg;
}

export { STX, ETX };

