// String-level passes over the serialized output.

import { AMP_SUBSTITUTE, HTML_PLACEHOLDER_PREFIX, ETX } from './constants.mjs';
import { replaceAll } from './chars.mjs';

/**
 * Splices stashed raw HTML back into the output.
 *
 * A stashed block that begins with a block-level tag would have been wrapped in
 * a paragraph by the block parser, so the surrounding `<p>` is removed on the
 * way back in. Stashed content can itself hold placeholders, so the pass
 * repeats until the output stops changing.
 */
export class RawHtmlPostprocessor {
  constructor(md) {
    this.md = md;
  }

  run(text) {
    const stash = this.md.htmlStash;
    if (stash.htmlCounter === 0) return text;

    const replacements = new Map();
    for (let i = 0; i < stash.htmlCounter; i++) {
      const html = String(stash.rawHtmlBlocks[i]);
      const placeholder = stash.getPlaceholder(i);
      if (this.isBlockLevel(html)) replacements.set('<p>' + placeholder + '</p>', html);
      replacements.set(placeholder, html);
    }

    const processed = this.substitute(text, replacements);
    if (processed === text) return processed;
    return this.run(processed);
  }

  /** Replace `<p>placeholder</p>` where present, otherwise bare placeholders. */
  substitute(text, replacements) {
    let out = '';
    let i = 0;
    while (i < text.length) {
      if (text.startsWith('<p>' + HTML_PLACEHOLDER_PREFIX, i)) {
        const span = this.readPlaceholder(text, i + 3);
        if (span && text.startsWith('</p>', span.end)) {
          const key = text.slice(i, span.end + 4);
          if (replacements.has(key)) { out += replacements.get(key); i = span.end + 4; continue; }
          if (replacements.has(span.key)) { out += replacements.get(span.key); i = span.end; continue; }
        }
      }
      if (text.startsWith(HTML_PLACEHOLDER_PREFIX, i)) {
        const span = this.readPlaceholder(text, i);
        if (span && replacements.has(span.key)) {
          out += replacements.get(span.key);
          i = span.end;
          continue;
        }
      }
      out += text[i];
      i++;
    }
    return out;
  }

  readPlaceholder(text, at) {
    if (!text.startsWith(HTML_PLACEHOLDER_PREFIX, at)) return null;
    let j = at + HTML_PLACEHOLDER_PREFIX.length;
    const digitsStart = j;
    while (j < text.length && text[j] >= '0' && text[j] <= '9') j++;
    if (j === digitsStart || text[j] !== ETX) return null;
    return { key: text.slice(at, j + 1), end: j + 1 };
  }

  /** Whether stashed markup starts with a tag that cannot sit inside a `<p>`. */
  isBlockLevel(html) {
    if (html[0] !== '<') return false;
    let i = 1;
    if (html[i] === '/') i++;
    const start = i;
    while (i < html.length && html[i] !== ' ' && html[i] !== '>') i++;
    if (i === start) return false;
    const name = html.slice(start, i);
    const lead = name[0];
    if (lead === '!' || lead === '?' || lead === '@' || lead === '%') return true;
    return this.md.isBlockLevel(name);
  }
}

/** Turns protected ampersands back into literal `&`. */
export class AndSubstitutePostprocessor {
  run(text) {
    return replaceAll(text, AMP_SUBSTITUTE, '&');
  }
}

export function buildPostprocessors(md, Registry) {
  const reg = new Registry();
  reg.register(new RawHtmlPostprocessor(md), 'raw_html', 30);
  reg.register(new AndSubstitutePostprocessor(), 'amp_substitute', 20);
  return reg;
}

