// The conversion pipeline.
//
//   preprocessors   -> line list  (normalize, pull out raw HTML)
//   block parser    -> element tree
//   treeprocessors  -> tree       (inline grammar, prettify, unescape)
//   serializer      -> string
//   postprocessors  -> string     (restore raw HTML, restore ampersands)

import { Registry } from './registry.mjs';
import { BlockParser } from './blockparser.mjs';
import { buildBlockParser } from './blockprocessors.mjs';
import { buildInlinePatterns, ESCAPED_CHARS } from './inlinepatterns.mjs';
import { buildTreeProcessors } from './treeprocessors.mjs';
import { buildPostprocessors } from './postprocessors.mjs';
import { NormalizeWhitespace } from './preprocessors.mjs';
import { HtmlBlockPreprocessor } from './htmlblock.mjs';
import { HtmlStash } from './htmlstash.mjs';
import { toHtmlString } from './serializer.mjs';
import { pyStrip, rstripChars } from './chars.mjs';
import { TAB_LENGTH, DOC_TAG, BLOCK_LEVEL_ELEMENTS } from './constants.mjs';

export class Markdown {
  constructor({ extensions = [], tabLength = TAB_LENGTH } = {}) {
    this.tabLength = tabLength;
    this.docTag = DOC_TAG;
    this.stripTopLevelTags = true;
    this.ESCAPED_CHARS = ESCAPED_CHARS.slice();
    this.blockLevelElements = BLOCK_LEVEL_ELEMENTS.slice();

    this.references = new Map();
    this.htmlStash = new HtmlStash();
    this.registeredExtensions = [];

    this.preprocessors = new Registry();
    this.preprocessors.register(new NormalizeWhitespace(this), 'normalize_whitespace', 30);
    this.preprocessors.register(new HtmlBlockPreprocessor(this), 'html_block', 20);

    this.parser = buildBlockParser(this, BlockParser, Registry);
    this.inlinePatterns = buildInlinePatterns(this, Registry);
    this.treeprocessors = buildTreeProcessors(this, Registry);
    this.postprocessors = buildPostprocessors(this, Registry);

    for (const ext of extensions) ext.extendMarkdown(this);
  }

  /** Tags that must not be wrapped in a paragraph. */
  isBlockLevel(tag) {
    if (typeof tag !== 'string') return false;
    return this.blockLevelElements.includes(rstripChars(tag.toLowerCase(), '/'));
  }

  registerExtension(ext) {
    this.registeredExtensions.push(ext);
  }

  reset() {
    this.htmlStash.reset();
    this.references.clear();
    for (const ext of this.registeredExtensions) {
      if (typeof ext.reset === 'function') ext.reset();
    }
    return this;
  }

  convert(source) {
    if (!pyStrip(source)) return '';

    let lines = source.split('\n');
    for (const prep of this.preprocessors) lines = prep.run(lines);

    let root = this.parser.parseDocument(lines);

    for (const tp of this.treeprocessors) {
      const next = tp.run(root);
      if (next !== null && next !== undefined) root = next;
    }

    let output = toHtmlString(root);

    if (this.stripTopLevelTags) {
      const open = '<' + this.docTag + '>';
      const close = '</' + this.docTag + '>';
      const start = output.indexOf(open);
      const end = output.lastIndexOf(close);
      if (start === -1 || end === -1) {
        if (pyStrip(output).endsWith('<' + this.docTag + ' />')) output = '';
        else throw new Error('Failed to strip top-level tags. Document=' + JSON.stringify(pyStrip(output)));
      } else {
        output = pyStrip(output.slice(start + open.length, end));
      }
    }

    for (const pp of this.postprocessors) output = pp.run(output);

    return pyStrip(output);
  }
}

/** One-shot conversion, mirroring the reference module-level helper. */
export function markdown(text, { extensions = [] } = {}) {
  return new Markdown({ extensions }).convert(text);
}

