      const end = output.lastIndexOf(close);
      if (start === -1 || end === -1) {
        if (pyStrip(output).endsWith('<' + this.docTag + ' />')) output = '';
        else throw new Error('Failed to strip top-level tags. Document=' + JSON.stringify(pyStrip(output)));
      } else {
        output = pyStrip(output.slice(start + open.length, end));
      }
    }

    for (const pp of this.postprocessors) output = pp.run(output);

    return pyStrip(output);
  }
}

/** One-shot conversion, mirroring the reference module-level helper. */
export function markdown(text, { extensions = [] } = {}) {
  return new Markdown({ extensions }).convert(text);
}
